    // Completeness invariant — every nav page must be documented.
    function auditSectionGuide() {
      const navPages = [...document.querySelectorAll('#sidebarProjectNav .nav-item[data-page]')]
        .map(el => el.dataset.page);
      const missing = navPages.filter(p => !SECTION_GUIDE[p]);
      const orphaned = Object.keys(SECTION_GUIDE).filter(k => !navPages.includes(k));
      return { missing, orphaned, ok: !missing.length && !orphaned.length };
    }

    // Generate nav tooltips from the registry so copy can never drift.
    function applyGuideTooltips() {
      document.querySelectorAll('#sidebarProjectNav .nav-item[data-page]').forEach(el => {
        const entry = SECTION_GUIDE[el.dataset.page];
        if (entry) el.setAttribute('data-tooltip', entry.tooltip);
      });
    }


