    /**
     * Show one reference picture at full size.
     *
     * ONE opener for every plate surface — the detail panel, the turnaround,
     * the location views and all three cards. Two would be how the grid and
     * the full-screen viewer came to normalise markup coordinates differently,
     * and how the board and the viewer came to disagree about their own tools.
     *
     * @param {string} src    already-resolved URL, API_BASE included
     * @param {string} title  what this is a picture OF — which view of which
     *                        subject, since a turnaround makes that ambiguous
     */
    function openPlateViewer(src, title) {
        if (!src) return;
        const img = document.getElementById('plateViewerImg');
        const meta = document.getElementById('plateViewerMeta');
        document.getElementById('plateViewerTitle').textContent = title || 'Reference';
        meta.textContent = '';
        img.onload = () => {
            // The size it was generated at, which is the thing a plate is
            // being judged on when someone opens it this large.
            meta.textContent = `${img.naturalWidth} \u00d7 ${img.naturalHeight}`;
        };
        img.onerror = () => { meta.textContent = 'The picture file is missing.'; };
        img.src = src;
        showModal('plateViewerModal');
    }

    /** Options from the SERVED vocabulary, with the current value selected. */
    function vocabOptions(list, current, blank) {
        return (blank ? `<option value="">${esc(blank)}</option>` : '')
            + (list || []).map(v => `<option value="${esc(v)}"${v === current ? ' selected' : ''}>`
                + `${esc(String(v).replace(/_/g, ' '))}</option>`).join('');
    }
    const money = n => '$' + (Number(n) || 0).toFixed(2);

    function usd(n) {
        if (!(n > 0)) return '$0.00';
        if (n < 0.01) return '$' + n.toFixed(4);
        if (n < 1) return '$' + n.toFixed(3);
        return '$' + n.toFixed(2);
    }

    // ══════════════════════════════════════════════════════════════
    // MODAL HELPERS
    // ══════════════════════════════════════════════════════════════
    /**
     * WHICH MODAL PAINTS ON TOP.
     *
     * Every `.modal-overlay` carries the same `z-index: 1000`, so paint order
     * fell to DOM order -- and `confirmGenModal` is declared near the top of the
     * file with THIRTY-ONE overlays after it, including both subject sheets. So
     * the pre-spend confirmation opened correctly, with the prompt, the model,
     * the quality and the size, UNDERNEATH the sheet it was launched from, where
     * it could be neither read nor clicked.
     *
     * Reported four times as "I still don't get the modal", and every time it
     * was there. Five test files passed throughout because they check that the
     * confirmation is INVOKED and that its markup is right; none of them could
     * see that it was invisible. A gate nobody can read is a gate that is not
     * there, and the generation went ahead anyway -- which is the spend the
     * whole mechanism exists to prevent.
     *
     * A DEPTH, not a running counter. A counter would work on the day it
     * shipped and climb for the life of the session, eventually clearing the top
     * bar and the sidebar. The stack holds what is actually open, so closing
     * gives the depth back.
     *
     * The base `z-index: 1000` stays in the stylesheet: a modal opened by
     * something that does not come through here must still APPEAR. This supplies
     * the ordering, not the visibility.
     */
    const MODAL_Z_BASE = 1000;
    const MODAL_STACK = [];

    function showModal(id) {
        const el = document.getElementById(id);
        if (!el) return;
        // Re-showing one already open RAISES it rather than counting it twice --
        // several flows re-enter a modal that is still open, and a double count
        // is a depth that never comes back down.
        const at = MODAL_STACK.indexOf(id);
        if (at >= 0) MODAL_STACK.splice(at, 1);
        MODAL_STACK.push(id);
        restackModals();
        el.classList.add('open');
        const firstInput = document.querySelector('#' + id + ' input[type="text"], #' + id + ' textarea');
        if (firstInput) setTimeout(() => firstInput.focus(), 50);
    }

    function closeModal(id) {
        const el = document.getElementById(id);
        const at = MODAL_STACK.indexOf(id);
        if (at >= 0) MODAL_STACK.splice(at, 1);
        restackModals();
        if (!el) return;
        el.classList.remove('open');
        // Given back, or a closed modal goes on sitting above the page.
        el.style.zIndex = '';
    }

    /**
     * Re-number the whole stack, bottom to top.
     *
     * Assigning only the modal that just moved leaves the one it was raised
     * ABOVE holding the same number -- equal z-index falls back to DOM order,
     * which is the bug this exists to end. Walking the stack is a handful of
     * elements and cannot drift out of step with itself.
     */
    function restackModals() {
        MODAL_STACK.forEach((mid, i) => {
            const m = document.getElementById(mid);
            if (m) m.style.zIndex = String(MODAL_Z_BASE + i + 1);
        });
    }

    /**
     * Build (or refill) a modal from HTML and show it.
     *
     * One helper rather than the create-or-reuse block copied per caller: three
     * modals were shown by adding a class the stylesheet does not display, so
     * they never appeared and their buttons read as dead. A caller that cannot
     * choose the class cannot get that wrong.
     */
    function showModalHtml(id, html) {
        const structured = /class=["'][^"']*\bmodal-(?:header|body)\b/.test(html);
        const content = structured ? html : `<div class="modal-body">${html}</div>`;
        let modal = document.getElementById(id);
        if (!modal) {
            modal = document.createElement('div');
            modal.id = id;
            modal.className = 'modal-overlay';
            modal.innerHTML = '<div class="modal">' + content + '</div>';
            document.body.appendChild(modal);
        } else {
            modal.querySelector('.modal').innerHTML = content;
        }
        // Delegated, so a modal built at run time stacks like every other one.
        showModal(id);
        return modal;
    }

    // Close on Escape
    document.addEventListener('keydown', e => {
        if (e.key === 'Escape') {
            const onboarding = document.getElementById('projectOnboardingModal');
            if (onboarding && onboarding.classList.contains('open')) {
                dismissProjectOnboarding();
            }
            document.querySelectorAll('.modal-overlay.open').forEach(m => {
                if (m.id !== 'projectOnboardingModal') closeModal(m.id);
            });
        }
        if (e.key === '?' && !e.metaKey && !e.ctrlKey && !e.altKey) {
            const tag = (e.target && e.target.tagName || '').toLowerCase();
            const isTyping = tag === 'input' || tag === 'textarea' || e.target?.isContentEditable;
            if (!isTyping) {
                e.preventDefault();
                openProductionGuide();
            }
        }
    });
    const MAX_CHUNK_SIZE = 7000;

    // FILM-119: Update estimate when text changes
    document.addEventListener('DOMContentLoaded', () => {
        const sourceText = document.getElementById('convertSourceText');
        if (sourceText) {
            let estimateTimer;
            sourceText.addEventListener('input', () => {
                clearTimeout(estimateTimer);
                estimateTimer = setTimeout(updateConversionEstimate, 500);
            });
        }
    });

    // FILM-119: Calculate and display estimated time
    function updateConversionEstimate() {
        const text = document.getElementById('convertSourceText').value;
        const estimateEl = document.getElementById('convertEstimate');

        if (!text.trim()) {
            estimateEl.style.display = 'none';
            return;
        }

        const textLength = text.length;
        const chunkCount = Math.ceil(textLength / MAX_CHUNK_SIZE);
        const estimatedSeconds = chunkCount * 15; // ~15 sec per chunk

        estimateEl.style.display = 'block';
        estimateEl.textContent = `Full document: ${textLength.toLocaleString()} chars (~${chunkCount} chunk${chunkCount !== 1 ? 's' : ''}, ~${Math.ceil(estimatedSeconds / 60)} min)`;
    }

    // Close on backdrop click
    document.querySelectorAll('.modal-overlay').forEach(overlay => {
        overlay.addEventListener('click', e => {
            if (e.target === overlay) closeModal(overlay.id);
        });
    });

    // ══════════════════════════════════════════════════════════════
    // INLINE SCREENPLAY COMMENTS
    // ══════════════════════════════════════════════════════════════
    let commentsVisible = false;
    let screenplayComments = [];


    async function loadScreenplayComments() {
        if (!state.currentProject) return;
        try {
            // Get latest script
            const scripts = await api('/projects/' + state.currentProject.id + '/scripts');
            const versions = scripts.versions || scripts.scripts || [];
            if (versions.length === 0) return;
            const latestId = versions[versions.length - 1].id || versions[0].id;
            const data = await api('/scripts/' + latestId + '/comments');
            screenplayComments = data.comments || [];
            renderCommentHighlights();
        } catch (err) { /* ignore */ }
    }

    async function addScreenplayComment() {
        if (!state.currentProject) return;
        const editor = document.getElementById('screenplayEditor');
        if (!editor) return;

        const sel = window.getSelection();
        if (!sel || sel.rangeCount === 0) {
            setStatus('Select text in the editor to add a comment');
            return;
        }

        const content = prompt('Enter comment:');
        if (!content) return;

        // Find element index
        const anchor = sel.anchorNode;
        let block = anchor?.nodeType === 3 ? anchor.parentElement : anchor;
        while (block && !block.dataset?.elementType && block !== editor) block = block.parentElement;
        if (!block || block === editor) return;

        const blocks = bodyBlocks(editor);
        const elementIndex = blocks.indexOf(block);

        try {
            const scripts = await api('/projects/' + state.currentProject.id + '/scripts');
            const versions = scripts.versions || scripts.scripts || [];
            if (versions.length === 0) return;
            const latestId = versions[versions.length - 1].id || versions[0].id;

            await api('/scripts/' + latestId + '/comments', {
                method: 'POST',
                body: JSON.stringify({
                    element_index: elementIndex,
                    start_offset: sel.anchorOffset || 0,
                    end_offset: sel.focusOffset || 0,
                    content,
                    author: 'user',
                }),
            });
            setStatus('Comment added');
            loadScreenplayComments();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    function renderCommentHighlights() {
        clearCommentHighlights();
        if (!commentsVisible || screenplayComments.length === 0) return;
        const editor = document.getElementById('screenplayEditor');
        if (!editor) return;

        // Show comment markers in the margin. Same list the anchor was written
        // against — element_index is an index into the BODY, not into the DOM.
        const blocks = bodyBlocks(editor);
        screenplayComments.forEach(c => {
            if (c.resolved) return;
            const block = blocks[c.element_index];
            if (!block) return;
            block.style.borderRight = '3px solid #f59e0b';
            block.title = (c.author || 'user') + ': ' + (c.content || '');
        });
    }

    function clearCommentHighlights() {
        const editor = document.getElementById('screenplayEditor');
        if (!editor) return;
        editor.querySelectorAll('[data-element-type]').forEach(b => {
            b.style.borderRight = '';
            b.title = '';
        });
    }

    // POST-based SSE (EventSource is GET-only). Streams `data: {json}\n\n` events.
    async function streamSSEPost(path, body, onEvent, onDone, onError) {
        try {
            const res = await fetch(API() + path, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(body || {}),
            });
            if (!res.ok || !res.body) {
                let detail = 'HTTP ' + res.status;
                try { const j = await res.json(); if (j && j.error) detail = j.error; } catch (_) {}
                const e = new Error(detail); e.status = res.status;
                onError?.(e); return;
            }
            const reader = res.body.getReader();
            const decoder = new TextDecoder();
            let buf = '';
            while (true) {
                const { done, value } = await reader.read();
                if (done) break;
                buf += decoder.decode(value, { stream: true });
                const chunks = buf.split('\n\n');
                buf = chunks.pop();
                for (const chunk of chunks) {
                    const line = chunk.split('\n').find(l => l.startsWith('data:'));
                    if (!line) continue;
                    let data; try { data = JSON.parse(line.slice(5).trim()); } catch { continue; }
                    if (data.type === 'done' || data.done) onDone?.(data);
                    else onEvent?.(data);
                }
            }
            onDone?.({ type: 'done' });
        } catch (err) { onError?.(err); }
    }

    // Generic per-entity action (backends already exist). `reload` refreshes the page.
    async function _shotAction(shotId, btn, label, path, running, reload, body) {
        if (btn) { btn.disabled = true; btn.textContent = running; }
        setStatus(running + '…');
        try {
            // The director's choices from the confirmation — an edited prompt,
            // a quality tier — travel with the request. Empty when there were
            // none, which is what every caller sent before.
            await api(path, { method: 'POST', body: JSON.stringify(body || {}) });
            setStatus(label + ' complete');
            (reload || loadVideoShots)();
        } catch (err) {
            setStatus(label + ' error: ' + err.message);
            if (btn) { btn.disabled = false; btn.textContent = label; }
        }
    }

    /* ── One audio file, as a card ──────────────────────────────────────────
     *
     * "Each audio file should be its own card with details about it — format,
     *  what it is, etc."
     *
     * The row this replaces said what a cue was CALLED and nothing about the
     * audio: not its format, length, weight, or what made it. A director
     * choosing between two takes of a score had nothing to choose on.
     *
     * Every fact is read from the asset row. Nothing is inferred and nothing is
     * invented — a card that guesses shows a confident blank where a fact
     * should be, and `film_assets` can already answer all five.
     */
    // ══════════════════════════════════════════════════════════════
    // MUSIC WORKSTATION (MUS-007) — the native multitrack editor
    //
    // The score session had a route and thirty tools and no page, so every
    // track, clip, range and marker could be written by an agent and by curl
    // and by nobody at a keyboard. This is that keyboard.
    //
    // ONE RULE FOR EVERY CONTROL: it carries data-mw="<table>:<field>" and
    // its change reaches mwSave, which PUTs the row through the session route
    // — the same validator the agent's write meets, so a refusal names the
    // field here exactly as it does there. Nothing is decided on the page:
    // the vocabulary, the ranges and the lifecycle table are SERVED
    // (/music-sessions/vocabulary) rather than typed a second time, which is
    // how a picker came to offer prop categories the CHECK refused.
    //
    // PLAYBACK SPENDS NOTHING. Clips are decoded once into an AudioContext and
    // scheduled from the playhead with their own source offset, gain, pan,
    // fades and loop policy — mute and solo decide what is heard, the way the
    // bounce will decide it. The waveform on each clip is the sound library's
    // own painter; a second painter is how two surfaces come to disagree
    // about what a file looks like.
    //
    // AUTOSAVE IS PER ROW, DEBOUNCED, AND SAYS WHAT HAPPENED. A slider fires
    // dozens of changes a second; each row saves once it settles, and the
    // status line says Saving / Saved / Save failed with the reason — a save
    // that fails silently is a director who believes their mix is kept.
    // ══════════════════════════════════════════════════════════════
    const MW = {
        sessions: [], session: null, model: null, brief: null, drift: null, vocab: null,
        selection: null, playheadMs: 0, playing: false, pxPerSec: 40,
        audio: null, buffers: {}, timers: {}, pending: {}, saveNote: '',
        raf: null, ctxStart: 0, msStart: 0, drag: null, sources: [],
        jobs: [], audition: null, emotionBox: '', daw: null, instruments: [], instrumentsError: null, rendering: null,
        open: {}, tab: {}, rollSel: null, snapDiv: 2,
    };
    function mwTime(ms) {
        const s = Math.max(0, Number(ms) || 0) / 1000;
        return Math.floor(s / 60) + ':' + String(Math.floor(s % 60)).padStart(2, '0') + '.' + String(Math.round((s % 1) * 10));
    }
    const DAW_ACTIONS = [
        { op: 'status', label: 'Check again', fn: 'dawRefresh', what: 'Is Live reachable through the sidecar, which version answered, and is it the reviewed one.', portable: { label: 'Export a score package', fn: 'dawExportPackage' } },
        { op: 'session_read', label: 'Read the Live set', fn: 'dawReadSession', what: 'The tracks in the Live set, which are Film Engine’s and which are somebody else’s.', portable: { label: 'Validate a package from any DAW', fn: 'dawImportPackage' } },
        { op: 'push_plan', label: 'Plan a push', fn: 'dawPlanPush', what: 'What a push would create, update and leave alone, and every track edited in Live since the last push.', portable: { label: 'Export a score package', fn: 'dawExportPackage' } },
        { op: 'push', label: 'Push this plan', fn: 'dawPush', what: 'Carry out exactly the plan reviewed here, into Film Engine’s own tracks, with every conflict decided.', portable: { label: 'Export a score package', fn: 'dawExportPackage' } },
        { op: 'pull_plan', label: 'What can come back', fn: 'dawPlanPull', what: 'The renders Live has that could come back into this session, with their hashes.', portable: { label: 'Import a package', fn: 'dawImportPackage' } },
        { op: 'pull', label: 'Bring back', fn: 'dawPull', what: 'One render back as candidate takes, imported only after its hash and alignment check out.', portable: { label: 'Import a package', fn: 'dawImportPackage' } },
        { op: 'transport', label: 'Play / stop / locate Live', fn: 'dawTransport', what: 'Move Live’s transport because you asked; nothing moves it on its own.', portable: { label: 'Play in the workstation', fn: 'mwTogglePlay' } },
    ];

    // Dialogue under a storyboard frame, the way a board is actually read:
    // character in caps, line beneath. The API has always returned this and the
    // panel dropped it, which left the board unable to answer "who says what
    // here" — the question a storyboard exists to answer alongside the picture.
    // ── Storyboard markup ──────────────────────────────────────────────────
    //
    // A director's fastest note is an arrow, not a sentence. Geometry is stored
    // NORMALISED (0..1 of the frame), so markup stays on the thing it points at
    // when the frame is regenerated at another size or the board is read on a
    // phone — pixels would drift the moment either happened.

    const MARKUP = {
        shotId: null, kind: null, canvasId: null, imgId: null,
        points: [], drawing: false,
        cache: {},        // shot id -> annotations, so a preview repaint is not a fetch
    };

    /** The six shapes, in the order a director reaches for them. */
    const MARKUP_KINDS = ['arrow', 'line', 'rect', 'ellipse', 'freehand', 'text'];

    /** A markup toolbar, for whichever surface is showing the frame. */

    /*
     * ── Blocking and directing, built once for both surfaces ──────────────
     *
     * These are two different jobs and the app offered neither completely.
     * BLOCKING is what is in the shot and where — characters, props, where they
     * stand. DIRECTING is where the camera goes — framing, lens, angle,
     * movement. The storyboard card editor had four directing fields and no
     * blocking fields at all; previs had the full camera and staged one
     * anonymous figure. So whichever surface you were on, half the job had no
     * controls.
     *
     * Built from one definition each, on the precedent markupToolbar already
     * set: two literals is exactly how the grid and the viewer came to disagree
     * about their own tools. The prefix produces the ids, so
     * directingPanel('shotCard') emits the ids the card modal was already wired
     * to and nothing existing has to be rewired to adopt it.
     */
    function blockingPanel(p, opts) {
        const o = opts || {};
        return `
        <div class="form-group">
            <label>What the screenplay says
                <span class="text-muted text-sm">the shot itself &mdash; editable, but this is the script's half</span>
            </label>
            <textarea id="${p}Written" rows="5"
                style="width:100%;line-height:1.55;font-family:inherit;"
                placeholder="What happens in this shot, as the screenplay has it."></textarea>
            <div class="text-sm text-muted" style="line-height:1.45;">
                Kept separate from Direction below so a screenplay revision can replace this half and
                leave your direction standing &mdash; and so the board shows the writing rather than a
                paraphrase of it.
            </div>
        </div>

        <!--
          WHAT THE SHOT SAYS.
          The card has carried its dialogue since the breakdown wrote it and no
          surface in this app displayed it: not here, not the board, not the
          production node, which passes a COUNT. So the one field that decides
          the voice track, and now the performance the video model is asked
          for, was invisible to the person directing it.
          Read-only on purpose. The screenplay is the source of truth for what
          is said, Resync reconciles these lines against it, and a second place
          to edit a line is how a board and a script come to disagree about the
          words an actor speaks.
        -->
        <div class="form-group" id="${p}DialogueGroup" hidden>
            <label>What is said
                <span class="text-muted text-sm">from the screenplay &mdash; edit it there, then Resync</span>
            </label>
            <div id="${p}Dialogue" style="line-height:1.6;"></div>
            <div class="text-sm text-muted" style="line-height:1.45;">
                Reaches the voice generation, and tells the video model whether a mouth in frame is
                moving. A line marked V.O. or O.S. does the opposite &mdash; it says nobody in frame speaks.
            </div>
        </div>

        <div class="form-group">
            <label>Direction
                <span class="text-muted text-sm">what you want on top of the screenplay &mdash; how it is blocked, what we see</span>
            </label>
            <textarea id="${p}Direction" rows="3"
                style="width:100%;line-height:1.55;font-family:inherit;"
                placeholder="Low and close on her. The dragon huge behind, out of focus, filling the top of frame."></textarea>
            <div class="text-sm text-muted" style="line-height:1.45;">
                Added to the screenplay, never replacing it &mdash; so a rewrite can replace its own half
                and leave your direction standing.
            </div>
        </div>

        <div class="form-group">
            <label>In this shot
                <span class="text-muted text-sm">each one you choose sends its reference plate with the frame</span>
            </label>
            <div id="${p}Subjects" data-blocking-kind="character"
                 style="display:flex;flex-direction:column;gap:12px;"></div>
        </div>`;
    }


    async function fillLocationViews(prefix, locationId, chosen) {
        const sel = document.getElementById(prefix + 'LocationView');
        const hint = document.getElementById(prefix + 'LocationViewHint');
        if (!sel) return;
        let views = [];
        try {
            if (locationId) views = (await api(`/locations/${locationId}/plate/views`)).views || [];
        } catch (_) { views = []; }

        const opts = views.map(v =>
            `<option value="${escapeHtml(v.view)}"${(v.view || '') === (chosen || '') ? ' selected' : ''}>`
            + `${escapeHtml(v.label)}</option>`).join('');
        sel.innerHTML = (views.length ? opts : '<option value="">— no plate yet —</option>')
            + '<option value="__new__">+ photograph a new view…</option>';

        if (hint) {
            hint.textContent = views.length > 1
                ? 'The view this shot is pointed at. Anything else falls back to the default plate.'
                : (views.length === 1
                    ? 'Only one view exists. A shot looking the other way gets this one — which is a '
                      + 'picture of what is behind its camera.'
                    : 'No location plate yet.');
        }
    }

    /** Picking "new view" asks for it and generates immediately. */
    /** Picking "a new view…" in a location dropdown photographs one. */
    async function locationViewChanged(prefix, locationId) {
        const sel = document.getElementById(prefix + 'LocationView');
        if (!sel || sel.value !== '__new__') return;
        sel.value = '';
        return addLocationView(locationId, () => {
            if (typeof loadLocations === 'function') loadLocations();
            if (typeof renderSubjectSheet === 'function' && SS && SS.id === locationId) renderSubjectSheet();
        });
    }

    /*
     * Who and what is in the shot, as a picker over what the project HAS.
     *
     * It was two free-text boxes. Typing "Maya" where the project says "MAYA"
     * silently invents a subject with no plate, no size and no locked profile —
     * and nothing says so, because the card happily stores any string. Choosing
     * from the project's own cast makes that unsayable, and lets the list show
     * the thing a director actually needs to know: which of these has a plate
     * and which will be invented from scratch in every frame.
     */
    function renderBlockingChoices(p, ctx) {
        const el = document.getElementById(p + 'Subjects');
        if (!el) return;
        const card = ctx.card || {};
        const chosen = kind => new Set((Array.isArray(card[kind]) ? card[kind] : [])
            .map(x => String(x).toLowerCase()));

        const groups = [
            { kind: 'character', key: 'characters', label: 'Characters', rows: ctx.characters || [] },
            { kind: 'prop', key: 'props', label: 'Props', rows: ctx.props || [] },
        ];

        let html = groups.map(g => {
            const on = chosen(g.key);
            if (!g.rows.length) {
                return `<div><strong class="text-sm">${g.label}</strong>
                    <div class="text-muted text-sm">This project has no ${g.kind}s yet.</div></div>`;
            }
            return `<div data-blocking-kind="${g.kind}">
                <strong class="text-sm">${g.label}</strong>
                <div style="display:flex;flex-wrap:wrap;gap:10px;margin-top:5px;">
                ${g.rows.map(r => {
                    const plated = !!r.has_plate;
                    return `<span style="display:inline-flex;gap:4px;align-items:center;">
                      <label style="display:flex;gap:6px;align-items:center;cursor:pointer;font-size:12px;"
                             title="${plated ? 'has a reference plate' : 'no plate yet — this subject is invented fresh in every frame'}">
                        <input type="checkbox" data-blocking="${g.key}" value="${escapeHtml(r.name)}"
                               ${on.has(String(r.name).toLowerCase()) ? 'checked' : ''}>
                        <span>${escapeHtml(r.name)}${plated ? '' : ' <span class="text-muted">(no plate)</span>'}</span>
                      </label>
                      ${plated ? `<label style="cursor:pointer;font-size:11px;"
                          title="Send ${escapeHtml(r.name)}'s plate even when an anchor is attached. An anchor covers where a subject STANDS; it covers who they ARE only if it shows them — a wide with someone's back to camera carries no face at all.">
                        <input type="checkbox" data-keep-plate value="${escapeHtml(r.name)}"> 📌
                      </label>` : ''}
                    </span>`;
                }).join('')}
                </div></div>`;
        }).join('');

        // The location is the scene's, not the shot's — shown so a director can
        // see what plate will attach, and switchable only in the sense of
        // choosing whether to send it.
        const loc = ctx.location;
        html += `<div data-blocking-kind="location">
            <strong class="text-sm">Location</strong>
            <div style="margin-top:5px;">${loc && loc.name
                ? `<label style="display:flex;gap:6px;align-items:center;cursor:pointer;font-size:12px;">
                     <input type="checkbox" id="${p}UseLocation" data-blocking="location" checked>
                     <span>${escapeHtml(loc.name)}${loc.has_plate ? '' : ' <span class="text-muted">(no plate)</span>'}
                     <span class="text-muted">&mdash; from the scene heading</span></span>
                   </label>
                   <div style="display:flex;gap:6px;align-items:center;margin-top:6px;">
                     <label class="text-sm text-muted" style="white-space:nowrap;">Seen from</label>
                     <select id="${p}LocationView" style="flex:1;font-size:12px;"
                             onchange="locationViewChanged('${p}', '${escapeHtml(loc.id || '')}')"></select>
                   </div>
                   <div class="text-sm text-muted" id="${p}LocationViewHint" style="line-height:1.45;"></div>`
                : '<span class="text-muted text-sm">This scene names no location, so no location plate can attach.</span>'}
            </div></div>`;
        el.innerHTML = html;
    }

    /** The cue extension on a line, from the field or from the name. */
    function cueExtensionOf(line) {
        if (!line) return '';
        const explicit = String(line.extension || '').trim();
        if (explicit) return explicit;
        const m = String(line.character || '').match(/\(([^)]+)\)\s*$/);
        return m ? m[1].trim() : '';
    }

    function fillBlockingPanel(p, card, shot) {
        const written = document.getElementById(p + 'Written');
        if (written) written.value = (card.description || '').trim();
        const dir = document.getElementById(p + 'Direction');
        if (dir) dir.value = card.direction || '';

        const group = document.getElementById(p + 'DialogueGroup');
        const host = document.getElementById(p + 'Dialogue');
        const lines = Array.isArray(card.dialogue) ? card.dialogue.filter(Boolean) : [];
        if (group) group.hidden = !lines.length;
        if (host) {
            host.innerHTML = lines.map(l => {
                const ext = cueExtensionOf(l);
                const who = String(l.character || '').replace(/\([^)]*\)\s*$/, '').trim();
                const off = /^(V\.?O\.?|O\.?S\.?|O\.?C\.?)$/i.test(ext.replace(/[\s.]+/g, ''));
                return `<div style="margin:0 0 8px;">
                    <div style="font-weight:600;letter-spacing:.04em;">${esc(who)}
                        ${ext ? `<span class="tag" style="margin-left:6px;border-color:${off
                            ? 'var(--gl-warning,#f59e0b)' : 'var(--gl-text-muted,#94a3b8)'};color:${off
                            ? 'var(--gl-warning,#f59e0b)' : 'var(--gl-text-muted,#94a3b8)'};"
                            title="${off ? 'Heard but not seen \u2014 no mouth in frame moves'
                                         : 'Spoken on camera'}">${esc(ext)}</span>` : ''}
                    </div>
                    <div style="padding-left:12px;">${esc(String(l.line || ''))}</div>
                </div>`;
            }).join('');
        }
    }

    /* The note is the one field nothing trims, so its length is worth seeing. */
    function cameraNoteCount(p) {
        const el = document.getElementById(p + 'Note');
        const out = document.getElementById(p + 'NoteCount');
        if (!el || !out) return;
        const n = (el.value || '').length;
        out.textContent = n ? `${n} of 400 characters` : '';
        out.style.color = n > 360 ? 'var(--warning,#b8860b)' : '';
    }

    /*
     * THE STYLE, PER SHOT. "Style of movie should be shown in the modal so I can
     * remove it or change it." The box shows what this shot sends: its own style
     * when it has one, else the film's. Editing makes it this shot's; "Use the
     * film style" puts it back to following the film (saved as null).
     */
    function shotCardStyleFill() {
        const box = document.getElementById('shotCardStyle');
        if (!box) return;
        const own = (SHOT_CARD.card.generation || {}).style;
        SHOT_CARD.styleMode = typeof own === 'string' ? 'shot' : 'film';
        box.value = typeof own === 'string' ? own : (SHOT_CARD.filmStyle || '');
        shotCardStyleSay();
    }
    function shotCardStyleSay() {
        const el = document.getElementById('shotCardStyleState');
        const box = document.getElementById('shotCardStyle');
        if (!el || !box) return;
        el.textContent = SHOT_CARD.styleMode === 'film'
            ? 'Following the film style (Settings). Edit it to give this shot its own.'
            : (box.value.trim() ? 'This shot\u2019s own style, saved on the shot.' : 'No style for this shot.');
    }
    function shotCardStyleEdited() { SHOT_CARD.styleMode = 'shot'; shotCardStyleSay(); }
    function shotCardStyleUseFilm() {
        const box = document.getElementById('shotCardStyle');
        if (box) box.value = SHOT_CARD.filmStyle || '';
        SHOT_CARD.styleMode = 'film';
        shotCardStyleSay();
    }
    function shotCardStyleNone() {
        const box = document.getElementById('shotCardStyle');
        if (box) box.value = '';
        SHOT_CARD.styleMode = 'shot';
        shotCardStyleSay();
    }
    window.shotCardStyleEdited = shotCardStyleEdited;
    window.shotCardStyleUseFilm = shotCardStyleUseFilm;
    window.shotCardStyleNone = shotCardStyleNone;

    function directingPanel(p, opts) {
        const o = opts || {};
        return `
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(165px,1fr));gap:12px;">
            <div class="form-group"><label>Shot size <span class="text-muted text-sm">EWS&ndash;ECU</span></label>
                <select id="${p}Framing" title="The one shot size the prompt says. Previs, when the shot is blocked, wins over this."></select>
                <div class="text-sm text-muted" id="${p}FramingHint"></div></div>
            <div class="form-group"><label>Shot type <span class="text-muted text-sm">angle or rig; a size word here only counts with no shot size set</span></label>
                <select id="${p}ShotType"></select>
                <div class="text-sm text-muted" id="${p}ShotTypeHint"></div></div>
            <div class="form-group"><label>Lens</label>
                <input type="text" id="${p}Lens" placeholder="40mm anamorphic">
                <div class="text-sm text-muted" id="${p}LensHint"></div></div>
            <div class="form-group"><label>Movement</label>
                <select id="${p}Movement"></select>
                <div class="text-sm text-muted" id="${p}MovementHint"></div></div>
            <!--
                MOTION. These reach the VIDEO prompt, not the frame — the
                keyframe already carries the look, so what a clip needs from
                words is what MOVES. environment_motion was read by the prompt
                builder and typeable nowhere, so "flames erupt from the struck
                house" could only be set by an agent or curl.
            -->
            <div class="form-group"><label>What the world does <span class="text-muted">(video)</span></label>
                <textarea id="${p}EnvMotion" data-field="environment_motion" rows="2"
                    placeholder="Flames erupt from the struck house; debris falls into the street."></textarea></div>
            <div class="form-group"><label>Where it ends <span class="text-muted">(video)</span></label>
                <textarea id="${p}EndState" data-field="end_state" rows="2"
                    placeholder="The creature fills the near foreground; the figure is small at the far kerb."></textarea></div>
            <div class="form-group"><label>Beats <span class="text-muted">(one per line, only if the shot has stages)</span></label>
                <textarea id="${p}Beats" data-field="beats" rows="3"
                    placeholder="the creature closes half the distance&#10;the wall is struck&#10;the figure turns"></textarea></div>
            <div class="form-group"><label>Must not appear <span class="text-muted">(frame and clip)</span></label>
                <textarea id="${p}NegPrompt" data-field="generation" rows="2"
                    placeholder="text, watermark, a second car, modern signage"></textarea></div>
            <div class="form-group"><label>Lighting <span class="text-muted text-sm">mood</span></label>
                <select id="${p}Lighting"></select>
                <div class="text-sm text-muted" id="${p}LightingHint"></div></div>
            <div class="form-group"><label>Lighting technique <span class="text-muted text-sm">where the lights stand</span></label>
                <select id="${p}LightTechnique"></select>
                <div class="text-sm text-muted">Blank takes the location's; the film's general look is the style.</div></div>
            <div class="form-group"><label>Key light from</label>
                <select id="${p}LightKeySide"><option value="">— the location's, else camera right —</option>
                    <option value="right">camera right</option><option value="left">camera left</option></select></div>
            <div class="form-group"><label>Camera height <span class="text-muted text-sm">m &mdash; the angle</span></label>
                <input type="number" step="0.1" min="0" id="${p}HeightM" placeholder="1.6">
                <div class="text-sm text-muted" id="${p}HeightMHint"></div></div>
            <div class="form-group"><label>Sensor</label>
                <select id="${p}Sensor"></select>
                <div class="text-sm text-muted" id="${p}SensorHint"></div></div>
            <div class="form-group"><label>Aperture <span class="text-muted text-sm">T-stop</span></label>
                <input type="number" step="0.1" min="0" id="${p}Aperture" placeholder="2.8">
                <div class="text-sm text-muted" id="${p}ApertureHint"></div></div>
            <div class="form-group"><label>Focus distance <span class="text-muted text-sm">m</span></label>
                <input type="number" step="0.1" min="0" id="${p}FocusDistanceM" placeholder="&mdash;">
                <div class="text-sm text-muted" id="${p}FocusDistanceMHint"></div></div>
        </div>
        <div class="form-group">
            <label>Camera note
                <span class="text-muted text-sm">one sentence about where the camera is &mdash; leads the prompt, never trimmed</span>
            </label>
            <textarea id="${p}Note" rows="2" maxlength="400"
                style="width:100%;line-height:1.5;font-family:inherit;"
                oninput="cameraNoteCount('${p}')"
                placeholder="Camera on the far side of the road, looking back toward her."></textarea>
            <div class="text-sm text-muted" id="${p}NoteCount"></div>
        </div>
        <p class="text-sm text-muted" style="margin:-4px 0 12px;line-height:1.5;">
            Leave anything blank and it falls through to the mood board, then to the film&rsquo;s look
            &mdash; each field says below it what it would inherit. Camera height IS the angle: at or
            below 0.9m the shot reads as looking up, at or above 2.2m as looking down.
            ${o.footer || ''}
        </p>`;
    }

    /*
     * What an unset facet would inherit.
     *
     * "Whatever options we don't add should take from either moodboard or
     * overall project look." A blank field that silently inherits is
     * indistinguishable from one that reaches nothing at all — which is how the
     * mood board's specs sat validated and consumed by nobody for weeks. Each
     * field states its own fallback, computed from the same specs generation
     * reads rather than written as placeholder text that would drift.
     */
    function directingFallbacks(specs) {
        const sp = specs || {};
        return {
            Framing: 'what Previs frames, else the size in the shot type',
            ShotType: 'whatever previs solves, or a medium',
            Lens: sp.lens ? `mood board: ${sp.lens}` : 'the film default',
            Movement: 'static, unless previs blocks a move',
            Lighting: "the scene's own time of day",
            HeightM: 'eye level (1.6m), or what previs staged',
            Sensor: sp.sensor ? `mood board: ${sp.sensor}` : 'the film default',
            Aperture: sp.aperture ? `mood board: T${sp.aperture}` : 'the film default',
            FocusDistanceM: 'the solved subject distance',
        };
    }

    function fillDirectingPanel(p, vocab, cam, lighting, fallbacks) {
        const light = lighting || {};
        if (document.getElementById(p + 'Framing')) {
            const fr = document.getElementById(p + 'Framing');
            fr.innerHTML = '<option value="">— from Previs, else the shot type —</option>'
                + (vocab.framings || []).map(f => `<option value="${esc(f.id)}" title="${esc(f.phrase)}">${esc(f.short)} &middot; ${esc(f.label)}</option>`).join('');
            fr.value = cam.framing || '';
        }
        shotCardFill(p + 'ShotType', vocab.shot_types, cam.shot_type, '— from the film —');
        shotCardFill(p + 'Movement', vocab.camera_moves, cam.movement, '— from the film —');
        shotCardFill(p + 'Lighting', vocab.lighting,
            typeof light === 'string' ? light : light.type, '— from the scene —');
        shotCardFill(p + 'Sensor', vocab.sensors || [], cam.sensor, '— from the film —');
        if (document.getElementById(p + 'LightTechnique')) {
            shotCardFill(p + 'LightTechnique', (vocab.lighting_techniques || []).map(t => t.id),
                typeof light === 'object' ? light.technique : '', '— from the location —');
            const ks = document.getElementById(p + 'LightKeySide');
            if (ks) ks.value = (typeof light === 'object' && light.key_side) || '';
        }
        const set = (id, v) => { const el = document.getElementById(id); if (el) el.value = (v === undefined || v === null) ? '' : v; };
        set(p + 'Lens', cam.lens);
        set(p + 'HeightM', cam.height_m);
        set(p + 'Aperture', cam.aperture);
        set(p + 'FocusDistanceM', cam.focus_distance_m);
        set(p + 'Note', cam.note);
        cameraNoteCount(p);

        for (const [field, text] of Object.entries(fallbacks || {})) {
            const hint = document.getElementById(p + field + 'Hint');
            if (!hint) continue;
            const el = document.getElementById(p + field);
            hint.textContent = (!el || el.value === '' || el.value === null) ? `\u21b3 ${text}` : '';
        }
    }

    function markupToolbar(shotId, canvasId, imgId) {
        const btn = k => `<button class="btn btn-sm" id="mk-${canvasId}-${k}"
            onclick="markupArm('${shotId}','${k}','${canvasId}','${imgId}')"
            title="drag on the frame to draw ${k === 'text' ? 'a note' : 'a ' + k}">${k}</button>`;
        return MARKUP_KINDS.map(btn).join('')
            + `<button class="btn btn-sm" onclick="markupUndo('${shotId}')" title="remove the last mark">undo</button>`
            + `<button class="btn btn-sm" onclick="markupClear('${shotId}')" title="remove all markup from this frame">clear</button>`
            + `<span id="mkfeed-${canvasId}" class="text-sm" style="opacity:.75;align-self:center;"></span>`;
    }

    // ── PAR-026: do these marks reach the next prompt? ─────────────────────
    //
    // The same arrows mean two different things depending on one project
    // setting, and nothing on the frame said which. A director who believes
    // their notes are steering generation when they are notation has been
    // misled by the app, not by the model.

    /** Whether this project's markup feeds generation. */
    function annotationFeedbackOn() {
        return !!(state.currentProject && state.currentProject.annotation_feedback);
    }

    /**
     * What this frame's marks will do, on the frame.
     *
     * Counted rather than assumed: geometry says where and never what, so a
     * shape with no note cannot reach a prompt however the project is set, and
     * a badge that counted all marks would promise something it cannot deliver.
     */
    function markupFeedBadge(shotId) {
        const marks = MARKUP.cache[shotId] || [];
        const noted = marks.filter(m => String(m.text || '').trim()).length;
        if (!marks.length) return '';
        if (!annotationFeedbackOn()) return `${marks.length} note(s), not applied`;
        if (!noted) return `${marks.length} mark(s) — none carry a note, so none apply`;
        return noted === marks.length
            ? `${noted} mark(s) steering this shot`
            : `${noted} of ${marks.length} steering this shot`;
    }

    /**
     * Arm a shape on a particular frame.
     *
     * Click-twice was the old gesture and it is not the one a hand makes. You
     * press where the arrow starts and release where it points; a shape that
     * needs two separate clicks with nothing drawn in between gives no feedback
     * on the first one, which is why the buttons read as broken.
     */
    function markupArm(shotId, kind, canvasId, imgId) {
        const canvas = document.getElementById(canvasId);
        if (!canvas) return;
        // Pressing the armed tool again disarms it, so there is a way out that
        // is not "draw something you did not want".
        if (MARKUP.shotId === shotId && MARKUP.kind === kind && MARKUP.canvasId === canvasId) {
            return markupDisarm();
        }
        markupDisarm();
        MARKUP.shotId = shotId; MARKUP.kind = kind;
        MARKUP.canvasId = canvasId; MARKUP.imgId = imgId;
        MARKUP.points = []; MARKUP.drawing = false;

        canvas.style.pointerEvents = 'auto';
        canvas.style.cursor = 'crosshair';
        // Visible where you are looking, not only in the status bar at the
        // bottom of the screen.
        canvas.style.outline = '2px solid var(--gl-brand-pink, #ec4899)';
        canvas.style.outlineOffset = '-2px';
        const tool = document.getElementById(`mk-${canvasId}-${kind}`);
        if (tool) tool.classList.add('btn-primary');

        canvas.onpointerdown = ev => markupDown(ev);
        canvas.onpointermove = ev => markupMove(ev);
        canvas.onpointerup = ev => markupUp(ev);
        canvas.onpointercancel = () => { MARKUP.drawing = false; MARKUP.points = []; markupPaint(); };

        setStatus(kind === 'text' ? 'Click where the note goes.' : `Drag to draw the ${kind}.`);
    }

    function markupDisarm() {
        const canvas = MARKUP.canvasId && document.getElementById(MARKUP.canvasId);
        if (canvas) {
            canvas.style.pointerEvents = 'none';
            canvas.style.outline = '';
            canvas.style.cursor = '';
            canvas.onpointerdown = canvas.onpointermove = canvas.onpointerup = canvas.onpointercancel = null;
        }
        const tool = MARKUP.canvasId && MARKUP.kind
            && document.getElementById(`mk-${MARKUP.canvasId}-${MARKUP.kind}`);
        if (tool) tool.classList.remove('btn-primary');
        MARKUP.shotId = null; MARKUP.kind = null; MARKUP.canvasId = null;
        MARKUP.imgId = null; MARKUP.points = []; MARKUP.drawing = false;
    }

    /**
     * Where the picture actually is inside its element.
     *
     * The full-screen viewer contains the frame with object-fit, so the image
     * occupies a letterboxed sub-rect of the element it is in. Normalising
     * against the ELEMENT would put every mark at the wrong place there while
     * looking perfectly right on the grid, where the two coincide — the kind of
     * error that is only ever found on the surface nobody tested.
     */
    function markupImageRect(img, canvas) {
        const r = canvas.getBoundingClientRect();
        const nw = img && img.naturalWidth, nh = img && img.naturalHeight;
        if (!nw || !nh) return { left: 0, top: 0, width: r.width, height: r.height };
        const scale = Math.min(r.width / nw, r.height / nh);
        const w = nw * scale, h = nh * scale;
        return { left: (r.width - w) / 2, top: (r.height - h) / 2, width: w, height: h };
    }

    /** True when the pointer is on the picture rather than on the letterbox. */
    function markupOnPicture(ev) {
        const canvas = document.getElementById(MARKUP.canvasId);
        const img = document.getElementById(MARKUP.imgId);
        const box = canvas.getBoundingClientRect();
        const rect = markupImageRect(img, canvas);
        const x = ev.clientX - box.left, y = ev.clientY - box.top;
        return x >= rect.left && x <= rect.left + rect.width
            && y >= rect.top && y <= rect.top + rect.height;
    }

    /** Pointer position as a fraction of the picture, clamped to it. */
    function markupPoint(ev) {
        const canvas = document.getElementById(MARKUP.canvasId);
        const img = document.getElementById(MARKUP.imgId);
        const box = canvas.getBoundingClientRect();
        const rect = markupImageRect(img, canvas);
        const x = (ev.clientX - box.left - rect.left) / (rect.width || 1);
        const y = (ev.clientY - box.top - rect.top) / (rect.height || 1);
        return [Math.min(1, Math.max(0, x)), Math.min(1, Math.max(0, y))];
    }

    function markupDown(ev) {
        ev.preventDefault();
        // The canvas covers the letterbox bars as well as the picture, and a
        // press there would clamp to the frame edge — a mark you did not place,
        // at a position you did not choose.
        if (!markupOnPicture(ev)) return;
        if (MARKUP.kind === 'text') return;              // text is placed on release
        MARKUP.drawing = true;
        MARKUP.points = [markupPoint(ev)];
        ev.currentTarget.setPointerCapture && ev.currentTarget.setPointerCapture(ev.pointerId);
    }

    function markupMove(ev) {
        if (!MARKUP.drawing) return;
        const p = markupPoint(ev);
        if (MARKUP.kind === 'freehand') {
            // Thinned as it is collected. A 60Hz drag across a frame is several
            // hundred points, and storing every one makes a row that is mostly
            // duplicates of the same millimetre.
            const last = MARKUP.points[MARKUP.points.length - 1];
            if (Math.hypot(p[0] - last[0], p[1] - last[1]) > 0.004) MARKUP.points.push(p);
        } else {
            MARKUP.points[1] = p;
        }
        markupPaint();
    }

    async function markupUp(ev) {
        const kind = MARKUP.kind, shotId = MARKUP.shotId;
        if (!kind) return;

        if (kind === 'text') {
            if (!markupOnPicture(ev)) return;
            const at = markupPoint(ev);
            const text = prompt('Note for this frame:');
            if (!text || !text.trim()) return;
            return markupCommit(shotId, 'text', [at], text.trim());
        }

        // The release point, not the last point the mouse happened to report
        // on its way there. They are close in a real drag and exactly equal in
        // none, and the gap is the difference between an arrow that lands where
        // you let go and one that lands slightly short of it.
        if (MARKUP.drawing && MARKUP.points.length) {
            const end = markupPoint(ev);
            if (kind === 'freehand') MARKUP.points.push(end);
            else MARKUP.points[1] = end;
        }
        MARKUP.drawing = false;
        const pts = MARKUP.points.slice();
        MARKUP.points = [];
        // A tap is not a shape. Staying armed rather than saving a zero-length
        // arrow means a missed drag costs one more try, not an undo.
        if (pts.length < 2) { markupPaint(); return setStatus(`Drag to draw the ${kind}.`); }
        if (kind !== 'freehand' && Math.hypot(pts[1][0] - pts[0][0], pts[1][1] - pts[0][1]) < 0.01) {
            markupPaint();
            return setStatus(`Too small — drag further to draw the ${kind}.`);
        }
        return markupCommit(shotId, kind, kind === 'freehand' ? pts : [pts[0], pts[1]], '');
    }

    async function markupCommit(shotId, kind, points, text) {
        try {
            const res = await api(`/shots/${shotId}/annotations`, {
                method: 'POST',
                body: JSON.stringify({ kind, points, text }),
            });
            (MARKUP.cache[shotId] = MARKUP.cache[shotId] || []).push(res.annotation);
            setStatus('Mark saved to the frame.');
        } catch (err) {
            setStatus('Could not save the mark: ' + err.message);
        }
        // Both surfaces repaint, because the same shot can be on screen twice —
        // the grid card behind the viewer that is open over it.
        markupPaintAll(shotId);
    }

    /** Fetch a shot's markup once and remember it. */
    async function markupLoad(shotId, force) {
        if (!force && MARKUP.cache[shotId]) return MARKUP.cache[shotId];
        try {
            const res = await api(`/shots/${shotId}/annotations`);
            MARKUP.cache[shotId] = res.annotations || [];
        } catch (_) { MARKUP.cache[shotId] = []; }
        return MARKUP.cache[shotId];
    }

    async function markupUndo(shotId) {
        const list = await markupLoad(shotId, true);
        const last = list[list.length - 1];
        if (!last) return setStatus('Nothing to undo on this frame.');
        try {
            await api(`/annotations/${last.id}`, { method: 'DELETE' });
            MARKUP.cache[shotId] = list.slice(0, -1);
            setStatus('Last mark removed.');
        } catch (err) { setStatus('Could not undo: ' + err.message); }
        markupPaintAll(shotId);
    }

    async function markupClear(shotId) {
        const list = await markupLoad(shotId, true);
        if (!list.length) return setStatus('No markup on this frame.');
        if (!confirm(`Remove all ${list.length} mark(s) from this frame?`)) return;
        try {
            for (const a of list) await api(`/annotations/${a.id}`, { method: 'DELETE' });
            MARKUP.cache[shotId] = [];
            setStatus('Markup cleared.');
        } catch (err) { setStatus('Could not clear: ' + err.message); }
        markupPaintAll(shotId);
    }

    /** Repaint every surface currently showing this shot. */
    async function markupPaintAll(shotId) {
        await markupLoad(shotId, true);
        markupPaintFeedBadge(shotId);
        markupDraw('annot-' + shotId, 'img-' + shotId, shotId);
        const f = (FRAME_VIEWER.frames || [])[FRAME_VIEWER.index];
        if (f && f.shot_id === shotId) markupDraw('frameViewerAnnot', 'frameViewerImg', shotId);
    }

    /** Repaint the armed surface, including the shape being dragged. */
    function markupPaint() {
        if (MARKUP.canvasId) markupDraw(MARKUP.canvasId, MARKUP.imgId, MARKUP.shotId);
    }

    /**
     * Paint a frame's markup — saved marks, plus the one under the cursor.
     *
     * The live shape is what makes this a drawing tool rather than a form: an
     * arrow you cannot see until it is stored is an arrow you place by guessing.
     */
    async function markupDraw(canvasId, imgId, shotId) {
        const canvas = document.getElementById(canvasId);
        if (!canvas || !shotId) return;
        const img = document.getElementById(imgId);
        const saved = await markupLoad(shotId);

        // Match the backing store to the displayed size, or every stroke draws
        // at the wrong scale on a high-DPI screen.
        const box = canvas.getBoundingClientRect();
        canvas.width = Math.max(1, Math.round(box.width));
        canvas.height = Math.max(1, Math.round(box.height));
        const ctx = canvas.getContext('2d');
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        const rect = markupImageRect(img, canvas);
        const px = p => [rect.left + p[0] * rect.width, rect.top + p[1] * rect.height];

        for (const a of saved) markupShape(ctx, a.kind, (a.points || []).map(px), a.text, a.color || '#f59e0b');

        const live = MARKUP.canvasId === canvasId && MARKUP.points.length >= 2 ? MARKUP.points : null;
        if (live) markupShape(ctx, MARKUP.kind, live.map(px), '', 'rgba(236,72,153,.95)');
    }

    function markupShape(ctx, kind, pts, text, colour) {
        if (!pts.length) return;
        ctx.strokeStyle = colour;
        ctx.fillStyle = colour;
        ctx.lineWidth = 2;
        ctx.lineJoin = 'round';
        ctx.lineCap = 'round';

        if (kind === 'text') {
            ctx.font = '600 13px system-ui, sans-serif';
            // A dark plate behind the text, because a note that lands on a
            // bright sky is a note nobody reads.
            const w = ctx.measureText(text || '').width;
            ctx.fillStyle = 'rgba(0,0,0,.6)';
            ctx.fillRect(pts[0][0] - 4, pts[0][1] - 14, w + 8, 19);
            ctx.fillStyle = colour;
            ctx.fillText(text || '', pts[0][0], pts[0][1]);
            return;
        }
        if (kind === 'rect') {
            ctx.strokeRect(pts[0][0], pts[0][1], pts[1][0] - pts[0][0], pts[1][1] - pts[0][1]);
            return;
        }
        if (kind === 'ellipse') {
            ctx.beginPath();
            ctx.ellipse((pts[0][0] + pts[1][0]) / 2, (pts[0][1] + pts[1][1]) / 2,
                Math.abs(pts[1][0] - pts[0][0]) / 2, Math.abs(pts[1][1] - pts[0][1]) / 2, 0, 0, Math.PI * 2);
            ctx.stroke();
            return;
        }
        ctx.beginPath();
        ctx.moveTo(pts[0][0], pts[0][1]);
        for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
        ctx.stroke();
        if (kind === 'arrow' && pts.length >= 2) {
            const [x1, y1] = pts[pts.length - 2], [x2, y2] = pts[pts.length - 1];
            const ang = Math.atan2(y2 - y1, x2 - x1), head = 12;
            ctx.beginPath();
            ctx.moveTo(x2, y2);
            ctx.lineTo(x2 - head * Math.cos(ang - Math.PI / 6), y2 - head * Math.sin(ang - Math.PI / 6));
            ctx.moveTo(x2, y2);
            ctx.lineTo(x2 - head * Math.cos(ang + Math.PI / 6), y2 - head * Math.sin(ang + Math.PI / 6));
            ctx.stroke();
        }
    }

    /**
     * Write "N marks steering this shot" onto whichever surfaces show it.
     *
     * The viewer's badge is guarded on the viewer actually showing THIS shot —
     * its element ids are fixed rather than per-shot, so painting it from any
     * repaint would label the open frame with another shot's count.
     */
    function markupPaintFeedBadge(shotId) {
        const badge = markupFeedBadge(shotId);
        const card = document.getElementById('mkfeed-annot-' + shotId);
        if (card) card.textContent = badge;
        const f = (FRAME_VIEWER.frames || [])[FRAME_VIEWER.index];
        const view = document.getElementById('mkfeed-frameViewerAnnot');
        if (view && f && f.shot_id === shotId) view.textContent = badge;
    }

    // ── Full-screen frame viewer ───────────────────────────────────────────
    //
    // A 260px card cannot answer whether a shot is right. Judging a frame means
    // seeing it at size, with the action and dialogue beside it, and being able
    // to step to the next one without going back to the grid — because
    // continuity is a comparison between frames, not a property of one.

    let FRAME_VIEWER = { frames: [], index: 0 };

    /**
     * Open the full-screen viewer on a shot.
     *
     * FRAME_VIEWER.frames is filled by loadStoryboard, so this used to be a
     * SILENT no-op from anywhere else: `if (i < 0) return`. The home page's
     * Resume button called it with a shot id and nothing happened at all — no
     * error, no message, exactly the failure mode a button wired to nothing has.
     *
     * It loads the board when it does not have it, and says so when the shot
     * genuinely is not there, rather than returning as though it had worked.
     */
    async function openFrameViewer(shotId) {
        markCurrentShot(shotId);
        let frames = FRAME_VIEWER.frames || [];
        let i = frames.findIndex(f => f.shot_id === shotId);
        if (i < 0) {
            await loadStoryboard();
            frames = FRAME_VIEWER.frames || [];
            i = frames.findIndex(f => f.shot_id === shotId);
        }
        if (i < 0) return setStatus('That shot is not on the board any more.');
        FRAME_VIEWER.index = i;
        showModal('frameViewerModal');
        frameViewerPaint();
    }

    function frameViewerStep(delta) {
        const n = (FRAME_VIEWER.frames || []).length;
        if (!n) return;
        // Wraps, so stepping past the end returns to the first rather than
        // stopping dead halfway through a board.
        FRAME_VIEWER.index = (FRAME_VIEWER.index + delta + n) % n;
        frameViewerPaint();
    }

    /** Which shot the viewer is showing, for the markup tools. */
    function frameViewerShotId() {
        const f = (FRAME_VIEWER.frames || [])[FRAME_VIEWER.index];
        return f ? f.shot_id : null;
    }

    function frameViewerPaint() {
        const f = (FRAME_VIEWER.frames || [])[FRAME_VIEWER.index];
        if (!f) return;
        // Stepping through the viewer moves the mark: otherwise it names the
        // shot you OPENED rather than the one you are looking at, which is the
        // kind of nearly-right that gets trusted and then quietly misleads.
        markCurrentShot(f.shot_id);
        // Stepping to another shot must not leave a tool armed on the one you
        // just left — the canvas is reused, so the next drag would land the
        // mark on the wrong frame.
        markupDisarm();
        document.getElementById('frameViewerTitle').textContent =
            `Sc${f.scene_number} / ${f.shot_code}  ·  ${FRAME_VIEWER.index + 1} of ${FRAME_VIEWER.frames.length}`;
        document.getElementById('frameViewerImg').src = frameSrc(f);
        // The same six shapes as the grid, because judging a frame at size is
        // exactly when you want to draw on it — and the note belongs to the
        // shot either way.
        document.getElementById('frameViewerTools').innerHTML =
            markupToolbar(f.shot_id, 'frameViewerAnnot', 'frameViewerImg')
            + `<span style="flex:1;"></span>`

            + `<button class="btn btn-sm btn-secondary" onclick="refineFrame('${f.shot_id}')">Refine</button>`
            + `<button class="btn btn-sm btn-secondary" onclick="regenerateStoryboard('${f.shot_id}')">Regen</button>`
            + `<button class="btn btn-sm btn-secondary" onclick="exploreAngles('${f.shot_id}')" title="Four separate images, one camera each. Pick one and it becomes the frame.">4 angles</button>`
            + `<button class="btn btn-sm btn-secondary" onclick="directShot('${f.shot_id}')" title="Who and what is in this shot, and where the camera is">Direct</button>`;
        document.getElementById('frameViewerCaption').innerHTML =
            `${f.description ? '<p style="line-height:1.5;">' + esc(f.description) + '</p>' : ''}
             ${storyboardDialogueHtml(f.dialogue)}`;
        markupDraw('frameViewerAnnot', 'frameViewerImg', f.shot_id);
        markupLoad(f.shot_id).then(() => markupPaintFeedBadge(f.shot_id));
    }

    // Arrow keys, because stepping a board is what hands do while eyes compare.
    document.addEventListener('keydown', ev => {
        const modal = document.getElementById('frameViewerModal');
        if (!modal || !modal.classList.contains('open')) return;
        if (ev.key === 'ArrowRight') frameViewerStep(1);
        if (ev.key === 'ArrowLeft') frameViewerStep(-1);
        if (ev.key === 'Escape') { markupDisarm(); closeModal('frameViewerModal'); }
    });

    /**
     * Shots the screenplay has left behind.
     *
     * Revising a scene does not update the cards derived from it, so those
     * cards go on describing the previous story — valid, correctly fingerprinted
     * and about a different film. On eight shots a director notices. On a
     * feature nobody does, and the first sign is a cut that makes no sense.
     */
    let DRIFT = { shots: {}, scenes: [] };

    function frameSrc(f, width) {
        const base = `${API_BASE}/film/storyboards/${state.currentProject.id}/${encodeURIComponent(f.shot_code)}.png`;
        const q = [];
        if (f.asset_version) q.push('v=' + f.asset_version);
        if (width) q.push('w=' + width);
        return q.length ? `${base}?${q.join('&')}` : base;
    }

    let SHOT_CARD = { shotId: null, card: null, vocab: null };

    /**
     * The lists a card may draw on, fetched once from the validator's own copy.
     *
     * Typing them into the page would work exactly once: a shot type added to
     * the schema would become an option the board offers and the validator
     * refuses. Same call the flows canvas made when it served its palette from
     * the node registry instead of a literal.
     */
    async function shotCardVocab() {
        if (SHOT_CARD.vocab) return SHOT_CARD.vocab;
        SHOT_CARD.vocab = await api('/card-vocabulary');
        return SHOT_CARD.vocab;
    }

    /** Fill a select from a list, with an explicit "not set" that means it. */
    function shotCardFill(id, values, current, blankLabel) {
        const el = document.getElementById(id);
        el.innerHTML = `<option value="">${blankLabel}</option>`
            + values.map(v => `<option value="${esc(v)}">${esc(v)}</option>`).join('');
        // A value the card carries but the list does not is kept rather than
        // silently reset — an old card must not lose a facet just by being
        // opened in the editor.
        if (current && !values.includes(current)) {
            el.innerHTML += `<option value="${esc(current)}">${esc(current)} (not in the current list)</option>`;
        }
        el.value = current || '';
    }

    /**
     * Change what a frame is generated from.
     *
     * The card is the only thing a regeneration reads, so a frame that came
     * back wrong could not be fixed inside the app at all. This was a one-line
     * prompt(), which is the wrong instrument twice over: a shot description is
     * a paragraph, and you cannot see the words you are editing in a field that
     * shows forty characters of them.
     */

    /**
     * What this shot would send, before any money is spent.
     *
     * GET /shots/:id/prompt costs nothing and returns the exact assembled
     * prompt, which plates travel with it, and how much room is left. It had no
     * control on the page at all, so the only way to find out what a shot would
     * send was to generate it and study the picture — which is what made
     * getting one frame right an afternoon of purchases.
     *
     * Everything that went wrong on 2B was visible here first: a camera note
     * contradicted by a staging line, a subject description overriding the
     * anchor, plates silently dropped for want of a slot.
     *
     * Deliberately not the budget chart this surface carried once. What a
     * director needs is the words going out, the pictures going with them, and
     * whether anything was cut.
     */
    /** What each part of a frame prompt is called on the Direct panel. */
    const PROMPT_PART_LABEL = Object.freeze({
        references: 'Pictures', camera_note: 'Camera note', plate: 'Plate', anchor: 'Anchor',
        direction: 'The shot', staging: 'Where people stand', camera: 'Camera', annotations: 'Marks',
        lighting: 'Lighting', style: 'Style', scale: 'Sizes', appearance: 'Unpictured subjects',
        location: 'Location (no picture)', contracts: 'Locked profiles', quality: 'Quality tags',
    });

    async function previewShotPrompt() {
        const box = document.getElementById('shotCardPreview');
        if (!box || !SHOT_CARD.shotId) return;
        const picked = document.querySelector('input[name="shotCardMode"]:checked');
        const mode = picked ? picked.value : 'action';
        box.innerHTML = '<span class="text-muted text-sm">Reading what this would send&hellip;</span>';
        try {
            const d = await api(`/shots/${SHOT_CARD.shotId}/prompt?direction_mode=${encodeURIComponent(mode)}`);
            const esc = escapeHtml;
            const cut = (d.budget || []).filter(b => b.cut > 0);
            CONFIRM_GEN_PROMPT = d.prompt || '';
            const staging = (d.prompt || '').match(/Staging:[^,]*(?:, [^,]*){0,6}/);
            const over = d.headroom !== null && d.headroom < 0;

            box.innerHTML = `
              <div class="card" style="padding:11px;">
                <div style="display:flex;justify-content:space-between;align-items:baseline;">
                  <strong class="text-sm">What this would send &mdash; costs nothing</strong>
                  <span class="text-sm ${over ? '' : 'text-muted'}"
                        style="${over ? 'color:var(--gl-danger,#ef4444);' : ''}">
                    ${d.prompt_chars} of ${d.ceiling}${d.headroom !== null ? ` &middot; ${d.headroom} spare` : ''}
                  </span>
                </div>
                ${d.direction_mode_blocked
                    ? `<div class="text-sm" style="color:var(--warning,#b8860b);margin-top:5px;">${esc(d.direction_mode_blocked)}</div>` : ''}
                <div class="text-sm" style="margin-top:7px;">
                  <strong>Travelling as pictures:</strong>
                  ${(d.references || []).length
                      ? (d.references || []).map(r => esc(
                          `${r.subject || '?'}${r.view ? ` — ${r.view}` : ''} (${r.kind || '?'})`)).join(', ')
                      : '<span class="text-muted">none &mdash; every subject is being invented from words</span>'}
                </div>
                <div class="text-sm" style="margin-top:8px;">
                  <strong>What goes into it, in order</strong>
                  <span class="text-muted">&mdash; everything that shapes this frame, and where it comes from</span>
                  <table style="width:100%;border-collapse:collapse;margin-top:4px;">
                    ${(d.budget || []).filter(b => b.text).map(b => `<tr style="vertical-align:top;border-top:1px solid rgba(255,255,255,.08);">
                        <td style="padding:4px 8px 4px 0;white-space:nowrap;"><strong>${esc(PROMPT_PART_LABEL[b.contributor] || b.contributor)}</strong></td>
                        <td style="padding:4px 0;line-height:1.45;">${esc(b.text)}${b.cut ? ` <span style="color:var(--warning,#b8860b);">(cut ${b.cut})</span>` : ''}</td>
                      </tr>`).join('')}
                  </table>
                  ${d.negative_not_sent ? `<div class="text-muted" style="margin-top:5px;line-height:1.45;">
                      <strong>Not sent:</strong> the "must not appear" list
                      (${esc(d.negative_not_sent)}) &mdash; ${esc(d.provider || 'this provider')} has no
                      negative field, and naming those things in the prompt draws them.</div>` : ''}
                  ${d.preview_error ? `<div style="color:var(--warning,#b8860b);margin-top:5px;">
                      Read from the card rather than the generation path: ${esc(d.preview_error)}</div>` : ''}
                </div>
                ${staging ? `<div class="text-sm" style="margin-top:5px;">
                    <strong>Staged geometry:</strong> ${esc(staging[0])}
                    <div class="text-muted" style="line-height:1.45;">
                        This comes from previs. If it disagrees with your camera note, the model is
                        being told two different things.
                    </div></div>` : ''}
                ${(d.off_frame || []).length ? `<div class="text-sm" style="margin-top:7px;">
                    <strong style="color:var(--warning,#b8860b);">Describing what is not in frame
                      (${d.off_frame.length}):</strong>
                    <div class="text-muted" style="line-height:1.45;">
                      An image model draws what you NAME, and negation is the least reliable
                      instruction it takes &mdash; so each of these puts the thing it excludes
                      into the picture.
                    </div>
                    <ul style="margin:4px 0 0 16px;padding:0;">
                      ${d.off_frame.map(f => `<li style="margin-bottom:3px;">
                          <code>${esc(f.phrase)}</code> &mdash; ${esc(f.fix)}</li>`).join('')}
                    </ul>
                  </div>` : ''}
                ${cut.length ? `<div class="text-sm" style="margin-top:5px;color:var(--warning,#b8860b);">
                    <strong>Cut to fit:</strong> ${cut.map(b => esc(`${b.contributor} (${b.cut} chars)`)).join(', ')}
                  </div>` : ''}
                <details style="margin-top:8px;">
                  <summary style="cursor:pointer;font-size:12px;">Read the whole prompt</summary>
                  <pre style="white-space:pre-wrap;font-size:11px;line-height:1.5;margin:6px 0 0;">${esc(d.prompt || '')}</pre>
                </details>
              </div>`;
        } catch (err) {
            box.innerHTML = `<span class="text-sm" style="color:var(--gl-danger,#ef4444);">Could not read it: ${escapeHtml(err.message)}</span>`;
        }
    }

    /**
     * Direct a shot: who and what is in it, then where the camera is.
     *
     * One modal, two questions. It was two things — an "Edit" that rewrote the
     * description and a "Direct" control panel with a seed, a sampler mode and
     * a character-budget chart — and neither was the job. The description is
     * the screenplay and is not a director's field; the machinery is the
     * engine's business. What is left is the work: block it, then shoot it.
     */
    const directShot = (shotId) => editShotCard(shotId);

    async function editShotCard(shotId, focusField) {
        try {
        markCurrentShot(shotId);
            const shot = await api(`/shots/${shotId}`);
            SHOT_CARD = { shotId, card: shot.card || {} };
            document.getElementById('shotCardTitle').textContent =
                `Edit Sc${shot.scene_number == null ? '?' : shot.scene_number} / ${shot.shot_code || 'shot'}`;

            // Both halves of the job, from the one definition each surface uses.
            document.getElementById('shotCardBlockingPanel').innerHTML = blockingPanel('shotCard');
            document.getElementById('shotCardDirectingPanel').innerHTML = directingPanel('shotCard');

            const vocab = await shotCardVocab();
            const cam = SHOT_CARD.card.camera || {};
            fillBlockingPanel('shotCard', SHOT_CARD.card, shot);

            /*
             * What this project actually has to choose from, and what the mood
             * board would supply for anything left blank. Both fetched here
             * rather than assumed, so the pickers can never offer a subject the
             * plates know nothing about and the fallback hints can never claim
             * an inheritance that is not really configured.
             */
            let ctx = { card: SHOT_CARD.card, characters: [], props: [], location: null };
            let specs = {};
            try {
                const pid = state.currentProject.id;
                const [chars, props, locs, board, proj] = await Promise.all([
                    api(`/projects/${pid}/characters`).catch(() => []),
                    api(`/projects/${pid}/props`).catch(() => []),
                    api(`/projects/${pid}/locations`).catch(() => []),
                    api(`/projects/${pid}/mood-board`).catch(() => ({})),
                    api(`/projects/${pid}`).catch(() => null),
                ]);
                const p0 = proj && (proj.project || proj);
                SHOT_CARD.filmStyle = (p0 && p0.style_preset) || '';
                /*
                 * `has_plate` comes from the server, derived from the same
                 * asset query the gatherer uses to attach a plate. This read
                 * three invented field names and so reported "no plate" for
                 * every subject in every project — the opposite of the truth,
                 * and the direction that costs money: it tells a director to go
                 * and generate plates that already exist.
                 */
                const platedBy = rows => (Array.isArray(rows) ? rows : [])
                    .map(r => ({ name: r.name, has_plate: !!r.has_plate }));
                ctx.characters = platedBy(chars.characters || chars);
                ctx.props = platedBy(props.props || props);
                const locRows = platedBy(locs.locations || locs);
                ctx.location = locRows.find(l => shot.location
                    && String(l.name).toLowerCase() === String(shot.location).toLowerCase())
                    || (shot.location ? { name: shot.location, has_plate: false } : null);
                for (const e of (board.entries || board || [])) {
                    if (e && e.spec_kind) specs[e.spec_kind] = e.spec_value;
                }
            } catch (_) { /* the panel still opens; it just offers less */ }

            renderBlockingChoices('shotCard', ctx);
            fillLocationViews('shotCard', ctx.location && ctx.location.id,
                SHOT_CARD.card.location_view || '');

            /*
             * Whether camera mode can actually run, said WHERE IT IS CHOSEN.
             * It is refused without an anchor, and meeting that as an error
             * after filling in a form is worse than being told while deciding.
             */
            const modeHint = document.getElementById('shotCardModeHint');
            const cameraRadio = document.querySelector('input[name="shotCardMode"][value="camera"]');
            if (modeHint && cameraRadio) {
                const a = BOARD_ANCHOR;
                const usable = a && a.shot_code && a.shot_id !== shotId;
                cameraRadio.disabled = !usable;
                modeHint.textContent = usable
                    ? `Camera mode will keep the scene from ${a.shot_code}.`
                    : (a && a.shot_id === shotId
                        ? 'This shot IS the anchor, so it generates from its own card.'
                        : 'No anchor set — pick a frame you like on the board and press ⚓ to use camera mode.');
            }
            fillDirectingPanel('shotCard', vocab, cam, SHOT_CARD.card.lighting, directingFallbacks(specs));
            // The motion fields are card-level, so they are filled here rather
            // than by fillDirectingPanel, which deals in camera facets.
            {
                const put = (id, v) => { const el = document.getElementById(id); if (el) el.value = v == null ? '' : v; };
                put('shotCardEnvMotion', SHOT_CARD.card.environment_motion);
                put('shotCardEndState', SHOT_CARD.card.end_state);
                put('shotCardBeats', Array.isArray(SHOT_CARD.card.beats) ? SHOT_CARD.card.beats.join('\n') : '');
                put('shotCardNegPrompt', (SHOT_CARD.card.generation || {}).negative_prompt);
            }
            shotCardStyleFill();

            document.getElementById('shotCardWarning').style.display = 'none';
            document.getElementById('shotCardPreview').innerHTML = '';
            showModal('shotCardModal');
            // What will be sent, shown as soon as the panel opens: every part
            // of the prompt and where it comes from. Free.
            previewShotPrompt();
            if (focusField) {
                const el = document.getElementById(focusField);
                if (el) setTimeout(() => { el.focus(); el.scrollIntoView({ block: 'center' }); }, 60);
            }
        } catch (err) {
            setStatus('Could not open the card: ' + err.message);
        }
    }

    function storyboardDialogueHtml(lines) {
        if (!Array.isArray(lines) || !lines.length) return '';
        const rows = lines.map(d => {
            const who = esc(String((d && (d.character || d.speaker)) || '').toUpperCase());
            const text = esc(String((d && (d.line || d.text || d.dialogue)) || (typeof d === 'string' ? d : '')));
            if (!text) return '';
            return '<div style="margin-top:6px;">'
                + (who ? '<div class="text-sm" style="font-weight:600;letter-spacing:.04em;">' + who + '</div>' : '')
                + '<div class="text-sm text-muted" style="font-style:italic;">&ldquo;' + text + '&rdquo;</div>'
                + '</div>';
        }).filter(Boolean).join('');
        if (!rows) return '';
        return '<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--gl-border,rgba(255,255,255,.12));">'
            + rows + '</div>';
    }

    /**
     * Regenerate one frame, visibly.
     *
     * This wrote "Regenerating..." to the status bar at the bottom of the
     * screen and then sat silent for up to a minute — an image call, plus a
     * provider chain that may walk past a declined provider before one accepts.
     * The card you clicked looked exactly as it had a moment earlier, so the
     * button read as broken and the honest response was to click it again,
     * which is how you pay twice.
     *
     * The frame being generated now says so, where you are looking, with the
     * elapsed count. Same reasoning as arming a markup shape: feedback belongs
     * on the thing you touched.
     */
    /**
     * Keep this picture and change one thing about it.
     *
     * Regen rebuilds the whole prompt from the card, so every subject reasserts
     * itself and the result is a new picture that happens to be of the same
     * shot — the wrong tool for "this one, but without the sprinkler", where
     * you spend a generation and lose the composition you liked in order to
     * change one object in it.
     *
     * This sends the frame itself and one sentence. None of the usual payload
     * goes with it: no scene card, no subject contracts, no style preset. The
     * picture already carries all of that, and repeating it in words pulls the
     * result back toward a fresh generation, which is the thing being avoided.
     */

    /**
     * What a REFINE would send — which is not what a regeneration would send.
     *
     * Refine carries the PICTURE plus one instruction: no scene card, no
     * subject descriptions, no style preset, because the picture already holds
     * all of that. This used to confirm against the regeneration preview, so it
     * displayed a ~3,800-character prompt and listed five plates that a refine
     * does not send — a dialog whose entire purpose is "see what will be sent"
     * being confidently wrong, which is worse than not having one.
     */

    /**
     * The two controls every paid image confirmation now carries, as markup the
     * rich path-specific dialogs can drop into their own layout.
     *
     * Refine and recompose lead with FILM FACTS — what is kept, which
     * background, what is adopted — and that is the reason they are not
     * replaced by the generic dialog. They gain the model picker and the
     * editable prompt; they do not lose the facts.
     */
    async function confirmExtras(prompt, ceiling, capability) {
        const pickers = await confirmPickers(capability);
        CONFIRM_GEN_PROMPT = prompt || '';
        CONFIRM_GEN_EDITED = false;
        return pickers + confirmPromptBox(prompt, ceiling);
    }

    /*
     * WHO MAKES IT AND WITH WHAT: provider, model, that provider's own options,
     * quality and size. Split from the prompt box because a read-only prompt
     * (a clip's motion prompt, a cue, a scene's dialogue) is not a reason to
     * hide the generator -- and it was: every video dialog showed no provider
     * picker at all, because the pickers only rendered beside an editable box.
     */
    async function confirmPickers(capability, how) {
        const cap = capability || 'image';
        // A clip dialog with its own priced tier row ("How good does this one
        // need to be?") must not draw a second, unpriced one beside it.
        const ownTiers = !!(how && how.ownTiers);
        CONFIRM_GEN_QUALITY = null;
        CONFIRM_GEN_PROVIDER = null;
        CONFIRM_GEN_MODEL = null;
        CONFIRM_GEN_SIZE = null;
        CONFIRM_GEN_CAP = cap;

        /*
         * Every dial SERVED, for the capability actually being generated.
         *
         * This used to fetch `.image_tiers` whatever was running, so a video or
         * music confirmation offered image tiers or nothing -- and VIDEO_TIERS
         * existed in the engine and reached no surface at all. It also called
         * `generatorPicker(o.capability)` where `o` is not a parameter of this
         * function, which threw a ReferenceError and took the refine and
         * recompose confirmations down with it.
         */
        let opts = null;
        let tierFacts = {};
        CONFIRM_GEN_DEFAULT = null;
        CONFIRM_GEN_OPTIONS = {};
        try {
            const cat = await api(`/projects/${state.currentProject.id}/providers`);
            opts = (cat.generation || {})[cap] || null;
            // Which provider runs when nobody picks one: its options are the
            // ones drawn before a pick, so "Project default" is not a blank.
            // An image tier's price and whether its provider has a key, which
            // the shot dialog showed on each tier button and must keep showing.
            tierFacts = Object.fromEntries(((cap === 'image' && cat.image_tiers) || []).map(t => [t.id, t]));
            const eff = (cat.effective || {})[cap];
            CONFIRM_GEN_DEFAULT = (eff && typeof eff === 'object') ? (eff.provider || eff.id || null) : (eff || null);
        } catch (_) { opts = null; }
        CONFIRM_GEN_OPTS = opts;

        const box = (title, inner, note, noteId) => `
          <div style="margin:10px 0;padding:9px 11px;border-radius:7px;background:rgba(255,255,255,.04);">
            <div class="text-sm" style="opacity:.7;margin-bottom:6px;">${esc(title)}</div>
            <div style="display:flex;gap:6px;flex-wrap:wrap;">${inner}</div>
            ${note ? `<div class="text-sm" style="opacity:.6;margin-top:6px;"${
                noteId ? ` id="${noteId}"` : ''}>${esc(note)}</div>` : ''}
          </div>`;

        /*
         * An uncredentialed generator is SHOWN AND DISABLED, never hidden.
         * Hiding it answers "which of these should I use" while withholding
         * "and this one is half the price if you sign up" -- the rule the
         * generator comparison already follows.
         */
        const providers = (opts && opts.providers) || [];
        const providerBox = providers.length < 2 ? '' : box('Generator for this one',
            `<button type="button" class="btn btn-sm" data-gen="" onclick="pickGenerator('')"
                     style="flex:1;min-width:110px;">Project default</button>`
            + providers.map(p => `<button type="button" class="btn btn-secondary btn-sm"
                    data-gen="${esc(p.id)}" onclick="pickGenerator('${esc(p.id)}')"
                    ${p.configured ? '' : 'disabled'} style="flex:1;min-width:110px;"
                    title="${p.configured ? '' : 'No API key stored for this generator'}">
                    ${esc(p.label || p.id)}${p.configured ? '' : ' · no key'}</button>`).join(''),
            'This generation only. Nothing is pinned to the project.', 'confirmGenProviderNote');

        const tiers = (opts && opts.tiers) || null;
        const tierBox = ownTiers ? '' : tiers && tiers.length ? box('Quality for this one',
            tiers.map(t => {
                const f = tierFacts[t.id] || {};
                return `<button type="button" class="btn btn-secondary btn-sm"
                    data-tier="${esc(t.id)}" onclick="pickGenQuality('${esc(t.id)}')"
                    ${f.available === false ? 'disabled' : ''}
                    style="flex:1;min-width:118px;" title="${esc(t.purpose || '')}">
                    ${esc(t.label || t.id)}${f.usd_per_image != null ? ` &middot; $${Number(f.usd_per_image).toFixed(3)}` : ''}</button>`;
            }).join(''),
            "Using this project's setting. Pick one to change it for this generation only.",
            'confirmGenQualityNote')
            : (opts && opts.tiers_note
                ? `<div class="text-sm text-muted" style="margin:8px 0;">${esc(opts.tiers_note)}</div>` : '');

        /*
         * Size, for the capabilities that have a raster. A director trying one
         * hero frame at 2K should not have to change a project setting and
         * change it back afterwards.
         */
        const sizes = (opts && opts.sizes) || null;
        const sizeBox = ownTiers ? '' : sizes && sizes.length ? box('Size for this one',
            `<button type="button" class="btn btn-sm" data-size="" onclick="pickGenSize('')"
                     style="flex:1;min-width:110px;">Project default</button>`
            + sizes.map(z => `<button type="button" class="btn btn-secondary btn-sm"
                    data-size="${esc(z.id)}" onclick="pickGenSize('${esc(z.id)}')"
                    style="flex:1;min-width:110px;">${esc(z.label || z.id)}</button>`).join(''),
            'The provider may serve the nearest size it offers, or ignore it entirely — the '
            + 'Compare Generators table says which do.', 'confirmGenSizeNote')
            : (opts && opts.sizes_note
                ? `<div class="text-sm text-muted" style="margin:8px 0;">${esc(opts.sizes_note)}</div>` : '');

        /*
         * The model slot is filled by pickGenerator, because a model only means
         * anything relative to a provider -- "Nano Banana Pro" is a Google
         * model and offering it beside Runway would be a choice the resolver
         * refuses. Empty until a generator is picked, which is also why it is a
         * container rather than markup rendered here.
         */
        return `
          ${providerBox}
          <div id="confirmGenModelBox"></div>
          ${cap === 'video' ? '' : '<div id="confirmGenOptionsBox"></div>'}
          ${tierBox}
          ${sizeBox}`;
    }

    /** The editable prompt, for the dialogs whose prompt can be edited. */
    function confirmPromptBox(prompt, ceiling) {
        const n = Number(ceiling) || 0;
        return `
          <div class="form-group">
            <label>The prompt
              <span class="text-sm text-muted" id="confirmGenChars">${(prompt || '').length}${n ? ` of ${n}` : ''}</span>
            </label>
            <textarea id="confirmGenPrompt" rows="7" spellcheck="false"
                oninput="confirmGenPromptEdited(${n})"
                style="width:100%;font-family:ui-monospace,Menlo,monospace;font-size:11px;line-height:1.5;
                       padding:8px;border-radius:6px;">${esc(prompt || '')}</textarea>
            <div class="text-sm text-muted" style="margin-top:4px;" id="confirmGenPromptNote">
              Edit it and the edited text is what gets sent, exactly as written.
            </div>
          </div>`;
    }

    function pickGenSize(id) {
        CONFIRM_GEN_SIZE = id || null;
        document.querySelectorAll('#confirmGenModal [data-size]').forEach(b => {
            b.classList.toggle('btn-secondary', b.dataset.size !== (id || ''));
        });
        const note = document.getElementById('confirmGenSizeNote');
        if (note) {
            note.textContent = id
                ? `This generation is asked for at ${id}. Nothing is pinned to the project.`
                : 'Using the project default size. Nothing is pinned to the project.';
        }
    }

    /** What the director chose in the confirmation just closed. */
    function confirmChoices() {
        const chosenOptions = CONFIRM_GEN_CAP === 'video' ? CONFIRM_GEN_VIDEO_OPTIONS : CONFIRM_GEN_OPTIONS;
        const optionsProvider = CONFIRM_GEN_PROVIDER || CONFIRM_GEN_DEFAULT;
        return {
            ...(CONFIRM_GEN_PROVIDER ? { provider: CONFIRM_GEN_PROVIDER } : {}),
            ...(CONFIRM_GEN_QUALITY ? { quality: CONFIRM_GEN_QUALITY } : {}),
            ...(CONFIRM_GEN_MODEL ? { model: CONFIRM_GEN_MODEL } : {}),
            ...(CONFIRM_GEN_SIZE ? { size: CONFIRM_GEN_SIZE } : {}),
            // The provider's own options, with the provider they were chosen
            // for: the server applies them only when that provider runs.
            ...(chosenOptions && Object.keys(chosenOptions).length ? { options: { ...chosenOptions } } : {}),
            ...(CONFIRM_GEN_CAP !== 'video' && optionsProvider && Object.keys(CONFIRM_GEN_OPTIONS).length
                ? { options_provider: optionsProvider } : {}),
            ...(CONFIRM_GEN_EDITED && confirmGenEditedPrompt()
                ? { prompt_override: confirmGenEditedPrompt() } : {}),
        };
    }

    async function confirmRefine(shotId, instruction, version, useAnchor) {
        const body = document.getElementById('confirmGenBody');
        const title = document.getElementById('confirmGenTitle');
        if (!body) return true;
        title.textContent = version ? `Refine v${version}` : 'Refine this frame';
        body.innerHTML = '<span class="text-muted text-sm">Reading what would be sent&hellip;</span>';
        confirmGenArm(false);
        showModal('confirmGenModal');
        const decision = new Promise(resolve => { CONFIRM_GEN = resolve; });

        try {
            const q = new URLSearchParams({ instruction });
            if (version) q.set('version', version);
            if (useAnchor) q.set('use_anchor', 'true');
            const d = await api(`/shots/${shotId}/storyboard/refine-preview?${q}`);
            const esc = escapeHtml;
            body.innerHTML = `
              <p class="text-sm text-muted" style="line-height:1.5;">${esc(d.note)}</p>
              <div class="form-group">
                <label>Pictures being sent (${d.references.length})</label>
                <ul style="margin:2px 0 0 16px;padding:0;">${d.references.map(r =>
                    `<li class="text-sm">${esc(r.subject)}
                       <span class="text-muted">&mdash; ${esc(r.kind)}</span></li>`).join('')}</ul>
                <div class="text-sm text-muted" style="line-height:1.45;">${esc(d.anchor_note)}</div>
              </div>
              <div class="form-group">
                <label>The whole instruction
                  <span class="text-muted text-sm">${d.prompt_chars} characters</span></label>
                <pre style="white-space:pre-wrap;font-size:11px;line-height:1.5;margin:0;padding:8px;
                            border-radius:6px;background:rgba(148,163,184,.10);display:none;">${esc(d.prompt)}</pre>
              </div>
              ${await confirmExtras(d.prompt, d.ceiling)}
              ${d.matched_against ? `<p class="text-sm text-muted">Matched against
                 <strong>${esc(d.matched_against)}</strong>.</p>` : ''}
              <p class="text-sm text-muted" style="line-height:1.45;">Costs credits. The frame you are
                 refining stays in the version list either way.</p>`;
            paintGenOptions(); confirmGenArm(true);
        } catch (err) {
            // Disarmed: a refine whose payload cannot be read is exactly the
            // blind spend this dialog exists to prevent.
            body.innerHTML = `<p class="text-sm" style="color:var(--gl-danger,#ef4444);">
                Could not read what would be sent: ${escapeHtml(err.message)}. Nothing will be
                generated — close this and try again.</p>`;
        }
        return decision;
    }


    /**
     * Keep a picture and change one thing about it.
     *
     * `version` is optional: without it this refines whatever the shot is
     * currently showing, which is the common case. WITH it, an earlier attempt
     * can be worked from directly — the route has always accepted a version and
     * the button never sent one, so reaching v20 meant SELECTING it first,
     * which changes what the whole board shows as a side effect of wanting to
     * try something.
     */
    async function refineFrame(shotId, version) {
        const instruction = prompt(
            (version ? `Refining v${version}.\n\n` : '')
            + 'What should change?\n\n'
            + 'ONE instruction. The picture is attached and already carries the scene, so do not '
            + 're-describe it — "move the car to the kerb", "make the light colder".');
        if (!instruction || !instruction.trim()) return;

        // Off by default: refine's contract is "keep this picture, change one
        // thing", and a second image arriving uninvited is what pulls it back
        // toward a fresh generation.
        const useAnchor = confirm(
            'Match the scene anchor as well?\n\n'
            + 'OK = attach the anchor frame so the location, dressing and grade match it.\n'
            + 'Cancel = refine this picture alone (the usual choice).');

        // The refine-specific confirmation: it leads with what a REFINE sends —
        // the picture plus one instruction — and now carries the model picker
        // and the editable prompt as well.
        const ok = await confirmRefine(shotId, instruction.trim(), version, useAnchor);
        if (!ok) return;
        const choices = confirmChoices();

        const done = frameBusy(shotId, 'Refining');
        setStatus('Refining frame...', true);
        try {
            const res = await api(`/shots/${shotId}/storyboard/refine`, {
                method: 'POST',
                body: JSON.stringify({
                    instruction: instruction.trim(),
                    ...(version ? { version } : {}),
                    use_anchor: useAnchor,
                    ...choices,
                }),
            });
            done();
            setStatus(res && res.matched_against
                ? `Frame refined, matched against ${res.matched_against}.`
                : 'Frame refined.');
            await loadStoryboard();
        } catch (err) { done(); setStatus('Could not refine: ' + err.message); }
    }
    /* The frame this project is currently shooting from, if any. */
    let BOARD_ANCHOR = null;


    /*
     * ── Nothing is generated before you have seen what is being sent ───────
     *
     * "When we click save or regen, we should have a popup of what will be sent
     * to the image generator, so I can check it before spending a credit. And
     * it should mention which plate or images are included so we're not going
     * blind."
     *
     * The free preview existed as a button you had to remember to press, which
     * is not the same thing: the check that matters is the one you cannot skip
     * by accident. Every paid path now goes through here.
     *
     * Naming the PICTURES is the half that was missing. A prompt reads
     * perfectly while the plate that would have made the car a 1970s sedan was
     * silently dropped for want of a reference slot — the words look right and
     * the frame comes back wrong, which is the most expensive kind of wrong.
     */
    let CONFIRM_GEN = null;
    /** The edited prompt, captured before the modal closes and the field is gone. */
    let CONFIRM_GEN_FINAL_PROMPT = null;
    function confirmGenEditedPrompt() { return CONFIRM_GEN_FINAL_PROMPT; }
    let CONFIRM_GEN_IGNORE_STAGED = false;

    /*
     * The Generate button is armed only by a preview that succeeded.
     *
     * It was left enabled after a preview error, so a failed inspection still
     * permitted the spend — which inverts a feature whose entire purpose is to
     * inspect before spending. Re-armed at the start of every confirmation, so
     * one failure cannot disarm the next.
     */
    function confirmGenArm(enabled) {
        const btn = document.getElementById('confirmGenGo');
        if (!btn) return;
        btn.disabled = !enabled;
        btn.title = enabled ? '' : 'Nothing can be generated until the preview can be read.';
    }

    /** The models the chosen generator actually offers, by name a director uses. */
    function paintGenModels(providerId) {
        const box = document.getElementById('confirmGenModelBox');
        if (!box) return;
        CONFIRM_GEN_MODEL = null;
        const p = ((CONFIRM_GEN_OPTS && CONFIRM_GEN_OPTS.providers) || [])
            .find(x => x.id === providerId);
        const models = (p && p.models) || [];
        if (!providerId || models.length < 2) { box.innerHTML = ''; return; }
        box.innerHTML = `
          <div style="margin:10px 0;padding:9px 11px;border-radius:7px;background:rgba(255,255,255,.04);">
            <div class="text-sm" style="opacity:.7;margin-bottom:6px;">Model on ${esc(p.label || p.id)}</div>
            <div style="display:flex;gap:6px;flex-wrap:wrap;">
              <button type="button" class="btn btn-sm" data-genmodel="" onclick="pickGenModel('')"
                      style="flex:1;min-width:110px;">Their default</button>
              ${models.map(m => `<button type="button" class="btn btn-secondary btn-sm"
                    data-genmodel="${esc(m.id)}" onclick="pickGenModel('${esc(m.id)}')"
                    style="flex:1;min-width:130px;"
                    title="${esc(m.sizes ? 'sizes: ' + m.sizes.join(', ') : '')}">
                    ${esc(m.label || m.id)}${m.sizes ? `<span class="text-sm" style="opacity:.6;"> · ${
                        esc(m.sizes[m.sizes.length - 1])}</span>` : ''}</button>`).join('')}
            </div>
            <div class="text-sm" style="opacity:.6;margin-top:6px;" id="confirmGenModelNote">
              This generation only.
            </div>
          </div>`;
    }

    /*
     * THE PICKED PROVIDER'S OWN OPTIONS, for everything that is not a clip
     * (a clip's are read from its preview, which re-prices them). Served with
     * the provider's models by the server from the adapter's own vocabulary, so
     * the dialog offers exactly what the request can carry. Before a pick, the
     * project's own provider's options are drawn.
     */
    function paintGenOptions() {
        const box = document.getElementById('confirmGenOptionsBox');
        if (!box) return;
        const id = CONFIRM_GEN_PROVIDER || CONFIRM_GEN_DEFAULT;
        const p = ((CONFIRM_GEN_OPTS && CONFIRM_GEN_OPTS.providers) || []).find(x => x.id === id);
        if (!p) { box.innerHTML = ''; return; }
        const m = CONFIRM_GEN_MODEL ? (p.models || []).find(x => x.id === CONFIRM_GEN_MODEL) : null;
        const controls = (m && m.options) || p.options || [];
        const notes = (m && m.option_notes) || p.option_notes || [];
        box.innerHTML = genOptionsHtml(p.label || p.id, controls, notes, p.option_source);
    }

    function setGenOption(key, value) {
        if (value === '' || value === null || value === undefined) delete CONFIRM_GEN_OPTIONS[key];
        else CONFIRM_GEN_OPTIONS[key] = value;
    }
    window.setGenOption = setGenOption;

    function genOptionsHtml(who, controls, notes, source) {
        if (!controls.length && !notes.length) {
            return `<div class="text-sm text-muted" style="margin:8px 0;">${esc(who)} takes no options here.</div>`;
        }
        const cur = k => (CONFIRM_GEN_OPTIONS[k] !== undefined ? CONFIRM_GEN_OPTIONS[k] : '');
        const field = (c, inner) => `<label class="vopt"><span>${esc(c.label)}</span>${inner}
            ${c.note ? `<small>${esc(c.note)}</small>` : ''}</label>`;
        const onSel = k => `onchange="setGenOption('${k}', this.value)"`;
        const html = controls.map(c => {
            const k = c.key;
            if (c.type === 'choice') {
                return field(c, `<select data-gopt="${esc(k)}" ${onSel(k)}>
                    <option value="">Default</option>
                    ${(c.choices || []).map(x => `<option value="${esc(String(x.id))}" ${
                        String(cur(k)) === String(x.id) ? 'selected' : ''}>${esc(x.label)}</option>`).join('')}
                  </select>`);
            }
            if (c.type === 'decimal' || c.type === 'range') {
                return field(c, `<span style="display:flex;gap:6px;align-items:center;">
                    <input type="number" data-gopt="${esc(k)}" min="${c.min}" max="${c.max}" step="${c.step || 1}"
                        value="${esc(String(cur(k)))}" placeholder="Default" ${onSel(k)} style="width:90px;">
                    <span class="text-sm text-muted">${c.min}–${c.max}${esc(c.unit || '')}</span></span>`);
            }
            if (c.type === 'toggle') {
                const d = c.default === true ? 'on' : c.default === false ? 'off' : 'the provider\'s';
                const v = cur(k) === '' ? '' : (cur(k) === true || cur(k) === 'true' ? 'true' : 'false');
                return field(c, `<select data-gopt="${esc(k)}" ${onSel(k)}>
                    <option value="">Default (${d})</option>
                    <option value="true" ${v === 'true' ? 'selected' : ''}>On</option>
                    <option value="false" ${v === 'false' ? 'selected' : ''}>Off</option></select>`);
            }
            if (c.type === 'number') {
                return field(c, `<input type="number" data-gopt="${esc(k)}" min="${c.min}" max="${c.max}" step="1"
                    value="${esc(String(cur(k)))}" placeholder="Random" ${onSel(k)}>`);
            }
            if (c.type === 'text') {
                return field(c, `<input type="text" data-gopt="${esc(k)}" maxlength="${c.max || 1000}"
                    value="${esc(String(cur(k)))}" ${onSel(k)}>`);
            }
            return '';
        }).join('');
        return `<div class="vopt-box">
            <div class="text-sm" style="opacity:.7;margin-bottom:6px;">Options on ${esc(who)}
              <span style="opacity:.7;">&middot; this one only</span></div>
            ${html ? `<div class="vopt-grid">${html}</div>` : ''}
            ${notes.map(n => `<div class="text-sm text-muted" style="margin-top:4px;line-height:1.45;">${esc(n)}</div>`).join('')}
            ${source ? `<div class="text-sm" style="opacity:.5;margin-top:6px;">From ${esc(source)}.</div>` : ''}
          </div>`;
    }

    function pickGenModel(id) {
        CONFIRM_GEN_MODEL = id || null;
        document.querySelectorAll('#confirmGenModal [data-genmodel]').forEach(b => {
            b.classList.toggle('btn-secondary', b.dataset.genmodel !== (id || ''));
        });
        const note = document.getElementById('confirmGenModelNote');
        if (note) note.textContent = id ? `Using ${id} for this generation only.` : 'This generation only.';
        // A different model takes different options: start again from its defaults.
        if (CONFIRM_GEN_CAP === 'video') { CONFIRM_GEN_VIDEO_OPTIONS = {}; repreviewVideo(); }
        else { CONFIRM_GEN_OPTIONS = {}; paintGenOptions(); }
    }

    function pickGenerator(id) {
        CONFIRM_GEN_PROVIDER = id || null;
        paintGenModels(id || '');
        if (CONFIRM_GEN_CAP === 'video') { CONFIRM_GEN_VIDEO_OPTIONS = {}; repreviewVideo(); }
        else { CONFIRM_GEN_OPTIONS = {}; paintGenOptions(); }
        document.querySelectorAll('#confirmGenModal [data-gen]').forEach(b => {
            b.classList.toggle('btn-secondary', b.dataset.gen !== (id || ''));
        });
        const note = document.getElementById('confirmGenProviderNote');
        if (note) {
            note.textContent = id
                ? `This generation goes to ${id}. Nothing is pinned to the project.`
                : 'Using the project default. Nothing is pinned to the project.';
        }
    }


    /*
     * The video tier row, and what it costs.
     *
     * A tier is a POLICY choice — how cheap, how good, how many attempts are
     * reasonable — so it belongs beside the Generate button rather than in a
     * settings page. Picking one re-reads the FREE preview, so the number under
     * the button is the number that will be charged, including the reference
     * images and any minimum.
     */
    let CONFIRM_GEN_VIDEO_TIER = null;
    let CONFIRM_GEN_PREVIEW_URL = null;

    const VIDEO_TIER_BLURB = {
        draft: 'Is the blocking right? The cheapest possible answer.',
        production: 'The shot as it will be cut, with the reference package.',
        hero: 'The shot the film is judged on. You pick the model.',
    };

    function videoEstimateHtml(d) {
        const e = d && d.estimate;
        // Runway prices in credits; MuAPI and the rest in dollars from the rate book.
        if (!e || !(e.credits || e.usd)) return '<div class="text-sm" style="opacity:.6;">No estimate available for this model.</div>';
        const refs = (d.references && d.references.sending) || 0;
        const dropped = (d.references && d.references.dropped) || [];
        return `
          <div style="display:flex;justify-content:space-between;align-items:baseline;">
            <strong style="font-size:15px;">$${Number(e.usd).toFixed(2)}</strong>
            <span class="text-sm" style="opacity:.6;">${e.credits ? `${e.credits} credits` : 'rate book'}${
                e.minimumApplied ? ' &middot; minimum applied' : ''}</span>
          </div>
          <div class="text-sm" style="opacity:.7;margin-top:5px;line-height:1.6;">
            ${(e.lines || []).map(l => `${esc(l.label)} &middot; ${l.credits != null ? l.credits + ' cr' : '$' + Number(l.usd || 0).toFixed(2)}`).join('<br>')}
          </div>
          ${refs ? `<div class="text-sm" style="opacity:.6;margin-top:5px;">Sending ${refs} reference${
                refs === 1 ? '' : 's'}: ${esc((d.references.roles || []).join(', '))}</div>` : ''}
          ${dropped.length ? `<div class="text-sm" style="color:var(--warning,#b8860b);margin-top:5px;">Not sent: ${
                esc(dropped.map(x => x.role + (x.subject ? ' ' + x.subject : '')).join(', '))}</div>` : ''}`;
    }

    function videoTierRow(d) {
        const ids = ['draft', 'production', 'hero'];
        const on = CONFIRM_GEN_VIDEO_TIER || d.tier || 'production';
        return `<div style="margin:10px 0;padding:9px 11px;border-radius:7px;background:rgba(255,255,255,.04);">
            <div class="text-sm" style="opacity:.7;margin-bottom:6px;">How good does this one need to be?</div>
            <div style="display:flex;gap:6px;flex-wrap:wrap;">
              ${ids.map(id => `<button type="button" class="btn ${id === on ? 'btn-primary' : 'btn-secondary'} btn-sm"
                  data-video-tier="${id}" onclick="pickVideoTier('${id}')"
                  style="flex:1;min-width:112px;text-transform:capitalize;">${id}</button>`).join('')}
            </div>
            <div class="text-sm" style="opacity:.6;margin-top:6px;">${esc(VIDEO_TIER_BLURB[on] || '')}</div>
            <div id="confirmVideoEstimate" style="margin-top:9px;">${videoEstimateHtml(d)}</div>
          </div>`;
    }

    async function pickVideoTier(id) {
        CONFIRM_GEN_VIDEO_TIER = id;
        return repreviewVideo();
    }
    window.pickVideoTier = pickVideoTier;

    /*
     * WHAT THIS MODEL LETS YOU CHOOSE, for this clip only: length, frame,
     * resolution, sound, the frame it ends on, output format, seed.
     *
     * Drawn from the PREVIEW's `options`, which the server reads from the
     * provider's own schema for the model this clip would actually run on. So
     * the dialog offers exactly what the request can carry, and changing the
     * generator, the model or the tier redraws them. Unset means "as the
     * project would have it", which is what every clip got before.
     */
    let CONFIRM_GEN_VIDEO_OPTIONS = {};
    let VIDEO_REPREVIEW_TIMER = null;

    function videoPreviewUrl() {
        const q = new URLSearchParams();
        if (CONFIRM_GEN_VIDEO_TIER) q.set('tier', CONFIRM_GEN_VIDEO_TIER);
        if (CONFIRM_GEN_PROVIDER) q.set('video', CONFIRM_GEN_PROVIDER);
        if (CONFIRM_GEN_MODEL) q.set('video_model', CONFIRM_GEN_MODEL);
        if (Object.keys(CONFIRM_GEN_VIDEO_OPTIONS).length) q.set('options', JSON.stringify(CONFIRM_GEN_VIDEO_OPTIONS));
        const qs = q.toString();
        return CONFIRM_GEN_PREVIEW_URL + (qs ? (CONFIRM_GEN_PREVIEW_URL.includes('?') ? '&' : '?') + qs : '');
    }

    async function repreviewVideo() {
        const holder = document.getElementById('confirmVideoTierRow');
        const opts = document.getElementById('confirmVideoOptions');
        if (!CONFIRM_GEN_PREVIEW_URL || (!holder && !opts)) return;
        if (holder) holder.innerHTML = '<div class="text-sm" style="opacity:.6;">Re-reading what this would cost&hellip;</div>';
        try {
            const d = await api(videoPreviewUrl());
            if (holder) holder.innerHTML = videoTierRow(d);
            if (opts) opts.innerHTML = videoOptionsHtml(d.options);
        } catch (err) {
            // A failed re-read must not leave a stale price under the button.
            if (holder) holder.innerHTML = `<div class="text-sm" style="color:var(--gl-danger,#ef4444);">
                Could not re-price this: ${esc(err.message)}</div>`;
        }
    }

    function setVideoOption(key, value) {
        if (value === '' || value === null || value === undefined) delete CONFIRM_GEN_VIDEO_OPTIONS[key];
        else CONFIRM_GEN_VIDEO_OPTIONS[key] = value;
        clearTimeout(VIDEO_REPREVIEW_TIMER);
        VIDEO_REPREVIEW_TIMER = setTimeout(repreviewVideo, 250);
    }
    window.setVideoOption = setVideoOption;

    function videoOptionsHtml(o) {
        if (!o) return '';
        const v = o.values || {};
        const chosen = CONFIRM_GEN_VIDEO_OPTIONS;
        const cur = k => (chosen[k] !== undefined ? chosen[k] : (v[k] !== undefined ? v[k] : ''));
        const field = (c, inner) => `<label class="vopt"><span>${esc(c.label)}</span>${inner}
            ${c.note ? `<small>${esc(c.note)}</small>` : ''}</label>`;
        const onSel = k => `onchange="setVideoOption('${k}', this.value)"`;
        const controls = (o.controls || []).map(c => {
            const k = c.key;
            if (c.type === 'choice') {
                return field(c, `<select data-vopt="${esc(k)}" ${onSel(k)}>
                    <option value="">Default</option>
                    ${(c.choices || []).map(x => `<option value="${esc(String(x.id))}" ${
                        String(cur(k)) === String(x.id) ? 'selected' : ''}>${esc(x.label)}</option>`).join('')}
                  </select>`);
            }
            if (c.type === 'range') {
                return field(c, `<span style="display:flex;gap:6px;align-items:center;">
                    <input type="number" data-vopt="${esc(k)}" min="${c.min}" max="${c.max}" step="${c.step || 1}"
                        value="${cur(k) === 'auto' ? '' : esc(String(cur(k)))}" placeholder="Shot's own"
                        onchange="setVideoOption('${k}', this.value)" style="width:90px;">
                    <span class="text-sm text-muted">${c.min}–${c.max}${esc(c.unit || '')}</span>
                    ${c.allow_auto ? `<label class="text-sm" style="display:flex;gap:4px;align-items:center;margin:0;">
                        <input type="checkbox" ${cur(k) === 'auto' ? 'checked' : ''}
                          onchange="setVideoOption('${k}', this.checked ? 'auto' : '')"> Auto</label>` : ''}
                  </span>`);
            }
            if (c.type === 'toggle') {
                const d = c.default === true ? 'on' : c.default === false ? 'off' : 'the provider\'s';
                const val = cur(k) === '' ? '' : (cur(k) === true || cur(k) === 'true' ? 'true' : 'false');
                return field(c, `<select data-vopt="${esc(k)}" ${onSel(k)}>
                    <option value="">Default (${d})</option>
                    <option value="true" ${val === 'true' ? 'selected' : ''}>On</option>
                    <option value="false" ${val === 'false' ? 'selected' : ''}>Off</option></select>`);
            }
            if (c.type === 'number') {
                return field(c, `<input type="number" data-vopt="${esc(k)}" min="${c.min}" max="${c.max}" step="1"
                    value="${esc(String(cur(k)))}" placeholder="Random" onchange="setVideoOption('${k}', this.value)">`);
            }
            if (c.type === 'text') {
                return field(c, `<input type="text" data-vopt="${esc(k)}" maxlength="${c.max || 1000}"
                    value="${esc(String(cur(k)))}" onchange="setVideoOption('${k}', this.value)">`);
            }
            if (c.type === 'frame') {
                return field(c, `<select data-vopt="${esc(k)}" ${onSel(k)}>
                    <option value="">No ending frame</option>
                    ${(o.frames || []).map(f => `<option value="${esc(f.id)}" ${
                        String(cur(k)) === String(f.id) ? 'selected' : ''}>${esc(f.label)}</option>`).join('')}
                  </select>`);
            }
            return '';
        }).join('');
        return `<div class="vopt-box">
            <div class="text-sm" style="opacity:.7;margin-bottom:6px;">Options on ${esc(o.model || o.provider || 'this model')}
              <span style="opacity:.7;">&middot; this clip only</span></div>
            ${controls ? `<div class="vopt-grid">${controls}</div>` : ''}
            ${(o.refused || []).map(r => `<div class="text-sm" style="color:var(--warning,#b8860b);">Not sent: ${esc(r)}</div>`).join('')}
            ${(o.notes || []).map(n => `<div class="text-sm text-muted" style="margin-top:4px;line-height:1.45;">${esc(n)}</div>`).join('')}
            ${o.source ? `<div class="text-sm" style="opacity:.5;margin-top:6px;">From ${esc(o.source)}, checked ${esc(o.checked || '')}.</div>` : ''}
          </div>`;
    }

    async function confirmPaidImage(o) {
        const body = document.getElementById('confirmGenBody');
        const title = document.getElementById('confirmGenTitle');
        if (!body) return o.send({});

        title.textContent = o.title || 'Before we spend a credit';
        body.innerHTML = '<span class="text-muted text-sm">Reading what would be sent&hellip;</span>';
        confirmGenArm(false);
        CONFIRM_GEN_PROMPT = null;
        CONFIRM_GEN_EDITED = false;
        CONFIRM_GEN_QUALITY = null;
        CONFIRM_GEN_PROVIDER = null;
        CONFIRM_GEN_VIDEO_TIER = null;
        CONFIRM_GEN_VIDEO_OPTIONS = {};
        CONFIRM_GEN_PREVIEW_URL = o.previewUrl || null;
        showModal('confirmGenModal');
        const decision = new Promise(resolve => { CONFIRM_GEN = resolve; });

        let d = null;
        try {
            // A plan whose input is structured (a range, a list of parts) is
            // read with a POST; it is still free and still writes nothing.
            d = o.previewBody
                ? await api(o.previewUrl, { method: 'POST', body: JSON.stringify(o.previewBody) })
                : await api(o.previewUrl);
        } catch (err) {
            // A gate that permits the spend when its own inspection failed is
            // worse than no gate: it teaches people the check happened.
            body.innerHTML = `<p class="text-sm" style="color:var(--gl-danger,#ef4444);">
                Could not read what would be sent: ${esc(err.message)}</p>`;
            confirmGenArm(false);
            await decision;
            return;
        }

        /*
         * A caller that knows what its plan says describes it itself: the
         * music workstation's plans carry the provider, the inputs, the
         * length, the outputs, the cost and the take behaviour, none of which
         * is an image prompt, and offering image dials there would be a
         * control that reaches nothing.
         */
        if (typeof o.describe === 'function') {
            body.innerHTML = `${o.note ? `<p class="text-sm text-muted" style="line-height:1.5;">${esc(o.note)}</p>` : ''}${o.describe(d)}`;
            // A plan can say nothing may run (nothing to run, over budget):
            // the caller's armable decides, so Confirm is never ready by default.
            confirmGenArm(o.armable ? !!o.armable(d) : true);
            const agreed = await decision;
            if (!agreed) return;
            return o.send({});
        }

        /*
         * The dials, for the capability actually being generated.
         *
         * This fetched `image_tiers` whatever was running, so a music or 3D
         * confirmation offered image quality tiers or nothing. `confirmExtras`
         * builds provider, model, quality and size from what the server serves
         * for this capability -- one builder, so the generic dialog and the
         * rich path-specific ones cannot come to offer different things.
         */
        /*
         * A pre-filled prompt ("make another like this") is offered in the box
         * in place of what the card would send today, and it counts as an
         * edit against today's prompt: the version's own words are the ones
         * that go, unless somebody changes them back.
         */
        const pickers = await confirmPickers(o.capability || 'image', { ownTiers: !!o.videoTiers });
        const promptBox = confirmPromptBox(o.prefill || d.prompt || '', Number(d.ceiling) || 0);

        const prompt = d.prompt || '';
        const ceiling = Number(d.ceiling) || 0;
        CONFIRM_GEN_PROMPT = prompt;
        CONFIRM_GEN_EDITED = !!(o.prefill && o.prefill !== prompt);

        body.innerHTML = `
          ${o.note ? `<p class="text-sm text-muted" style="line-height:1.5;">${esc(o.note)}</p>` : ''}
          ${(d.notes || []).map(n => `<p class="text-sm" style="color:var(--warning,#b8860b);line-height:1.5;">${esc(n)}</p>`).join('')}

          <div class="text-sm text-muted" style="margin:8px 0;">
            ${esc(d.provider || 'provider unknown')}${d.model ? ' &middot; ' + esc(d.model) : ''}
            ${d.estimated_cost ? ` &middot; <strong>${d.estimated_cost.native != null
                ? d.estimated_cost.native + ' ' + esc(d.estimated_cost.native_unit || '') + ' ≈ ' : ''}$${
                Number(d.estimated_cost.usd).toFixed(3)}</strong>` : ''}
          </div>

          ${pickers}
          ${o.videoTiers ? `<div id="confirmVideoTierRow">${videoTierRow(d)}</div>` : ''}
          ${o.capability === 'video' && d.options ? `<div id="confirmVideoOptions">${videoOptionsHtml(d.options)}</div>` : ''}
          ${deliveryLineHtml(d.delivery)}
          ${dialogueAudioRowHtml(d.dialogue_audio)}

          ${o.editable === false
              ? `<div class="form-group">
                   <label>The prompt
                     <span class="text-sm text-muted">${(d.prompt || '').length}${
                        Number(d.ceiling) ? ` of ${Number(d.ceiling)}` : ' characters'}</span>
                   </label>
                   <pre style="white-space:pre-wrap;font-size:11px;line-height:1.5;max-height:260px;overflow:auto;
                        margin:0;padding:8px;border-radius:6px;background:rgba(148,163,184,.10);">${esc(d.prompt || '')}</pre>
                   <div class="text-sm text-muted" style="margin-top:4px;">${esc(o.notEditableWhy || '')}</div>
                 </div>`
              : promptBox}
        `;
        CONFIRM_GEN_PROMPT = prompt;
        CONFIRM_GEN_EDITED = !!(o.prefill && o.prefill !== prompt);
        paintGenOptions();

        confirmGenArm(true);
        const ok = await decision;
        if (!ok) return;

        const dlg = document.getElementById('confirmDialogueAudio');
        return o.send({
            ...(dlg && dlg.checked ? { use_dialogue_audio: true } : {}),
            ...confirmChoices(),
        });
    }

    async function confirmGeneration(shotId, opts) {
        const o = opts || {};
        const body = document.getElementById('confirmGenBody');
        const title = document.getElementById('confirmGenTitle');
        if (!body) return true;

        title.textContent = o.title || 'Before we spend a credit';
        body.innerHTML = '<span class="text-muted text-sm">Reading what would be sent&hellip;</span>';
        confirmGenArm(false);
        CONFIRM_GEN_IGNORE_STAGED = false;
        CONFIRM_GEN_PROMPT = null;
        CONFIRM_GEN_EDITED = false;
        showModal('confirmGenModal');

        const decision = new Promise(resolve => { CONFIRM_GEN = resolve; });

        try {
            const q = o.mode ? `?direction_mode=${encodeURIComponent(o.mode)}` : '';
            const d = await api(`/shots/${shotId}/prompt${q}`);
            const esc = escapeHtml;
            const refs = d.references || [];
            const cut = (d.budget || []).filter(b => b.cut > 0);
            const staging = (d.prompt || '').match(/Staging:[^,]*(?:, [^,]*){0,6}/);
            const over = d.headroom !== null && d.headroom < 0;

            /*
             * WHICH GENERATOR, chosen for this one frame.
             *
             * The tier is a project setting, and that is the right default and
             * the wrong granularity for the moment that actually matters: a
             * director looking at a frame that came back wrong wants to spend
             * more on THIS one, and a director trying three compositions wants
             * to spend less — neither wants to change a setting and remember to
             * put it back, which is how a whole board ends up shot on the
             * expensive tier because of one difficult shot.
             *
             * It belongs on the confirmation rather than in the Direct panel
             * because this is the gate every paid image path already passes
             * through, and it is where the price is already in front of you.
             */
            // The same pickers every other generate button has: any connected
            // provider, its models, its own options, quality and size. This
            // dialog offered the quality tier and nothing else, so the shot
            // node's Generate on the Production graph could not choose who
            // made the frame.
            const pickers = await confirmPickers('image');

            body.innerHTML = `
              ${o.note ? `<p class="text-sm text-muted" style="line-height:1.5;">${esc(o.note)}</p>` : ''}

              ${pickers}

              ${d.staged_notice ? `<p class="text-sm" style="color:var(--warning,#b8860b);line-height:1.5;">
                  <strong>${d.card_ahead || d.conflict ? 'Resolve the board/Previs conflict.' : 'Apply this Previs first.'}</strong>
                  ${esc(d.staged_notice)}</p>` : ''}

              <div class="form-group">
                <label>Continuity</label>
                ${(() => {
                    const anchored = refs.find(r => r.kind === 'anchor');
                    if (anchored) {
                        return `<div class="text-sm">Built from <strong>${esc(anchored.subject)}</strong>
                            &mdash; its location, dressing and subject placement, re-shot on this
                            shot's own lens and angle.</div>`;
                    }
                    /*
                     * The absence of an anchor is the single biggest reason a
                     * shot's location does not match the rest of its scene, and
                     * it was invisible: the anchor is a toggle on a frame card,
                     * easy to put down by accident, and nothing on the way to a
                     * generation said it was gone. A missing plate among five is
                     * hard to spot; a missing ANCHOR changes the whole street.
                     */
                    return `<div class="text-sm" style="color:var(--warning,#b8860b);">
                        <strong>No anchor.</strong> The location will be built from words and the
                        location plate alone, so the road, the kerb and where things stand may not
                        match the other shots in this scene.
                        <div class="text-muted" style="line-height:1.45;">
                          Cancel, press &#9875; on the frame whose staging you want to keep, then
                          generate this one again.
                        </div></div>`;
                })()}
              </div>

              <div class="form-group">
                <label>Pictures travelling with this prompt (${refs.length})</label>
                ${refs.length
                    ? `<ul style="margin:2px 0 0 16px;padding:0;">${refs.map(r =>
                        `<li class="text-sm">${esc(r.subject || '?')}${r.view
                            ? ` <span class="text-muted">&mdash; ${esc(r.view)}</span>` : ''}
                          <span class="text-muted">&mdash; ${esc(r.kind || '?')}</span></li>`).join('')}</ul>`
                    : `<div class="text-sm" style="color:var(--warning,#b8860b);">
                         None. Every subject will be invented from words alone &mdash; if a plate exists
                         for one of them, it is not being sent.</div>`}
              </div>

              ${staging ? `<div class="form-group">
                  <label>Staged geometry</label>
                  <div class="text-sm">${esc(staging[0])}</div>
                  <div class="text-sm text-muted" style="line-height:1.45;">
                    From previs. If this disagrees with your camera note, the model is being told
                    two different things.</div>
                </div>` : ''}

              ${(d.off_frame || []).length ? `<div class="form-group">
                  <label style="color:var(--warning,#b8860b);">
                    Describing what is not in frame (${d.off_frame.length})</label>
                  <div class="text-sm text-muted" style="line-height:1.45;">
                    An image model draws what you NAME, so each of these puts the thing it excludes
                    into the picture.</div>
                  <ul style="margin:3px 0 0 16px;padding:0;">${d.off_frame.map(f =>
                    `<li class="text-sm"><code>${esc(f.phrase)}</code> &mdash; ${esc(f.fix)}</li>`).join('')}</ul>
                </div>` : ''}

              ${cut.length ? `<div class="text-sm" style="color:var(--warning,#b8860b);margin-bottom:8px;">
                  <strong>Cut to fit:</strong> ${cut.map(b => esc(`${b.contributor} (${b.cut} chars)`)).join(', ')}
                </div>` : ''}

              ${d.direction_mode_blocked
                  ? `<div class="text-sm" style="color:var(--warning,#b8860b);margin-bottom:8px;">
                       ${esc(d.direction_mode_blocked)}</div>` : ''}

              <div class="form-group">
                <label>The prompt
                  <span class="text-sm ${over ? '' : 'text-muted'}" id="confirmGenChars"
                        style="${over ? 'color:var(--gl-danger,#ef4444);' : ''}">
                    ${d.prompt_chars} of ${d.ceiling}${d.headroom !== null ? ` &middot; ${d.headroom} spare` : ''}
                  </span>
                </label>
                ${o.editable === false
                    ? `<pre style="white-space:pre-wrap;font-size:11px;line-height:1.5;max-height:260px;overflow:auto;
                            margin:0;padding:8px;border-radius:6px;background:rgba(148,163,184,.10);">${esc(d.prompt || '')}</pre>`
                    : `<textarea id="confirmGenPrompt" rows="9" spellcheck="false"
                          oninput="confirmGenPromptEdited(${Number(d.ceiling) || 0})"
                          style="width:100%;font-family:ui-monospace,Menlo,monospace;font-size:11px;line-height:1.5;
                                 padding:8px;border-radius:6px;">${esc(d.prompt || '')}</textarea>
                       <div class="text-sm text-muted" style="margin-top:4px;" id="confirmGenPromptNote">
                         Edit it and the edited text is what gets sent, exactly as written &mdash; the
                         engine will not add references or the style preset on top of it.
                       </div>`}
              </div>`;
            paintGenOptions();
            // A preview may inspect an experiment, but a paid Board action may
            // not silently consume it. Apply staged blocking, or re-seed when
            // the board is newer, then reopen this confirmation.
            if (d.staged || d.card_ahead || d.conflict) {
                // Exploration is not a dead end. This deliberate override shoots
                // the committed card while leaving the staged Previs untouched.
                CONFIRM_GEN_IGNORE_STAGED = true;
                const go = document.getElementById('confirmGenGo');
                if (go) go.textContent = 'Generate from board anyway';
                confirmGenArm(true);
            } else {
                const go = document.getElementById('confirmGenGo');
                if (go) go.textContent = 'Generate';
                confirmGenArm(true);
            }
        } catch (err) {
            /*
             * Disarmed rather than "you can still generate blind".
             *
             * The earlier wording let a director proceed past a failed
             * inspection, which is the one thing this gate exists to stop. If
             * the payload cannot be read, the honest state is that nothing is
             * generated.
             */
            body.innerHTML = `<p class="text-sm" style="color:var(--gl-danger,#ef4444);">
                Could not read what would be sent: ${escapeHtml(err.message)}. Nothing will be
                generated — close this and try again.</p>`;
        }

        return decision;
    }

    let CONFIRM_GEN_QUALITY = null;
    let CONFIRM_GEN_PROVIDER = null;
    let CONFIRM_GEN_MODEL = null;
    let CONFIRM_GEN_SIZE = null;
    let CONFIRM_GEN_CAP = 'image';
    let CONFIRM_GEN_OPTS = null;
    let CONFIRM_GEN_DEFAULT = null;     // the provider that runs when none is picked
    let CONFIRM_GEN_OPTIONS = {};       // that provider's own options, for this one
    let CONFIRM_GEN_PROMPT = null;      // the text as it was offered
    let CONFIRM_GEN_EDITED = false;

    /**
     * The prompt is editable, and an edit is FINAL.
     *
     * `GET /shots/:id/prompt` shows exactly what would be sent and the route
     * takes that text back as `prompt_override` — the two have existed for
     * weeks with nothing between them, so composing a prompt by hand meant
     * curl. This is the missing half: read what is going, change it, send it.
     *
     * An override is the WHOLE prompt, not a prefix: the route sets
     * promptIsFinal, so nothing is appended afterwards. That has to be said
     * where the editing happens, or a director edits one clause expecting the
     * references and the style to still be added and gets neither.
     */
    function confirmGenPromptEdited(ceiling) {
        const box = document.getElementById('confirmGenPrompt');
        if (!box) return;
        CONFIRM_GEN_EDITED = box.value !== CONFIRM_GEN_PROMPT;
        const chars = document.getElementById('confirmGenChars');
        if (chars && ceiling) {
            const n = box.value.length;
            chars.textContent = `${n} of ${ceiling}${n <= ceiling ? ` · ${ceiling - n} spare` : ' · OVER'}`;
            chars.style.color = n > ceiling ? 'var(--gl-danger,#ef4444)' : '';
        }
        const note = document.getElementById('confirmGenPromptNote');
        if (note && CONFIRM_GEN_EDITED) {
            note.textContent = 'Edited — this exact text is what will be sent. References and the '
                + 'style preset are NOT added on top of an edited prompt.';
        }
    }

    function pickGenQuality(tier) {
        CONFIRM_GEN_QUALITY = tier;
        document.querySelectorAll('#confirmGenModal [data-tier]').forEach(b => {
            const on = b.dataset.tier === tier;
            b.classList.toggle('btn-secondary', !on);
        });
        const note = document.getElementById('confirmGenQualityNote');
        // Says it applies to this frame only, where the choice is made — a
        // per-call override that looks like a setting is one people expect to
        // have changed the project.
        if (note) note.textContent = `This frame only. The project's own setting is unchanged.`;
    }

    /*
     * FOUR ANGLES, THEN "USE B".
     *
     * Four separate generations, one camera each, at the project's resolution
     * — the director chose separate images over one grid so the picked one is
     * ready for the board as it is. The free preview shows the four prompts and
     * the price of four; nothing replaces the frame until a pick.
     */
    async function exploreAngles(shotId) {
        markCurrentShot(shotId);
        return confirmPaidImage({
            title: 'Explore four angles',
            note: 'Four separate images, one camera each. The board frame is not touched until you pick one.',
            previewUrl: '/shots/' + shotId + '/storyboard/angles-preview',
            describe: d => {
                const sp = d.spend || {};
                const cost = sp.usd_total != null
                    ? `<strong>$${Number(sp.usd_total).toFixed(2)}</strong> for ${sp.images} images (${esc(sp.provider || '')}, $${Number(sp.usd_each).toFixed(3)} each${sp.estimated ? ', estimated' : ''})`
                    : esc(sp.note || `${sp.images || 4} images`);
                return `<div class="text-sm text-muted" style="margin:6px 0;">${esc(d.model || '')} &middot; ${esc(d.resolution || '')} &middot; ${cost}</div>
                  ${(d.angles || []).map(a => `<details style="margin:6px 0;"><summary><strong>${esc(a.slot)}</strong> &middot; ${esc(a.label)} <span class="text-muted">${a.width}x${a.height}</span></summary>
                    <pre style="white-space:pre-wrap;font-size:11px;opacity:.8;max-height:160px;overflow:auto;">${esc(a.prompt || '')}</pre></details>`).join('')}`;
            },
            send: async () => {
                setStatus('Exploring four angles...', true);
                try {
                    const r = await api('/shots/' + shotId + '/storyboard/angles', { method: 'POST', body: JSON.stringify({}) });
                    setStatus('Angle A is ready; the other three are generating.');
                    openAngleSheet(shotId, r.token);
                } catch (err) { setStatus('Could not explore angles: ' + err.message); }
            },
        });
    }

    let ANGLE_POLL = null;
    async function openAngleSheet(shotId, token) {
        const html = `<div class="modal-header"><h3>Four angles</h3>
              <button class="btn btn-sm btn-secondary" onclick="closeAngleSheet()">Close</button></div>
            <div id="angleSheetBody" class="modal-body"><span class="text-muted text-sm">Loading&hellip;</span></div>`;
        const modal = showModalHtml('angleSheetModal', html);
        const box = modal && modal.querySelector('.modal');
        if (box) { box.style.maxWidth = '1100px'; box.style.width = '94vw'; }
        const paint = async () => {
            let d;
            try { d = await api('/shots/' + shotId + '/storyboard/angles/' + token); }
            catch (err) {
                const el = document.getElementById('angleSheetBody');
                if (el) el.innerHTML = `<p class="text-sm" style="color:var(--gl-danger,#ef4444);">${esc(err.message)}</p>`;
                return true;
            }
            const el = document.getElementById('angleSheetBody');
            if (!el) return true;
            const bySlot = Object.fromEntries((d.candidates || []).map(c => [c.slot, c]));
            const slots = ['A', 'B', 'C', 'D'];
            el.innerHTML = `<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
                ${slots.map(sl => {
                    const c = bySlot[sl];
                    const state = (d.slots && d.slots[sl]) || (c ? 'ready' : 'waiting');
                    return `<div style="border:1px solid rgba(255,255,255,.12);border-radius:8px;padding:8px;min-width:0;">
                      <div class="text-sm" style="margin-bottom:6px;"><strong>${sl}</strong> &middot; ${esc(c ? c.label : state)}${c && c.picked ? ' &middot; <em>on the board</em>' : ''}</div>
                      ${c ? `<img src="${API_BASE}${c.image_url}" style="width:100%;border-radius:6px;display:block;cursor:zoom-in;" onclick="openPlateViewer(this.src, 'Angle ${sl}')">
                        <button class="btn btn-primary btn-sm" style="margin-top:6px;" onclick="pickAngle('${shotId}','${token}','${sl}')">Use ${sl}</button>`
                        : `<div class="text-sm text-muted" style="padding:40px 0;text-align:center;">${esc(state)}&hellip;</div>`}
                    </div>`;
                }).join('')}
              </div>
              ${(d.failed || []).length ? `<p class="text-sm" style="color:var(--gl-danger,#ef4444);">${(d.failed).map(f => `${esc(f.slot)}: ${esc(f.error)}`).join('<br>')}${(d.not_attempted || []).length ? `<br>Not attempted: ${esc(d.not_attempted.join(', '))}` : ''}</p>` : ''}
              ${d.sheet_url ? `<p class="text-sm"><a href="${API_BASE}${d.sheet_url}" target="_blank" rel="noopener">Open the contact sheet</a></p>` : ''}`;
            return d.status && d.status !== 'running';
        };
        clearInterval(ANGLE_POLL);
        if (!(await paint())) ANGLE_POLL = setInterval(async () => { if (await paint()) clearInterval(ANGLE_POLL); }, 3000);
    }

    function closeAngleSheet() {
        clearInterval(ANGLE_POLL);
        const m = document.getElementById('angleSheetModal');
        if (m) closeModal('angleSheetModal');
    }

    async function pickAngle(shotId, token, slot) {
        try {
            const r = await api('/shots/' + shotId + '/storyboard/angles/' + token + '/pick', {
                method: 'POST', body: JSON.stringify({ slot }) });
            setStatus(`Angle ${slot} is on the board as v${r.version}.`);
            openAngleSheet(shotId, token);
        } catch (err) { setStatus('Could not use that angle: ' + err.message); }
    }
    window.exploreAngles = exploreAngles;
    window.openAngleSheet = openAngleSheet;
    window.closeAngleSheet = closeAngleSheet;
    window.pickAngle = pickAngle;

    async function regenerateStoryboard(shotId, directionMode, keepPlates) {
        markCurrentShot(shotId);
        const ok = await confirmGeneration(shotId, {
            mode: directionMode,
            title: 'Regenerate this frame',
            note: 'This replaces the current image and costs credits. The frame it replaces stays in '
                + 'the version list.',
        });
        if (!ok) return;
        const done = frameBusy(shotId, 'Generating');
        setStatus('Regenerating frame...', true);
        try {
            const res = await api('/shots/' + shotId + '/storyboard/regenerate', {
                method: 'POST',
                body: JSON.stringify({
                    ...(directionMode ? { direction_mode: directionMode } : {}),
                    ...(keepPlates && keepPlates.length ? { keep_plates: keepPlates } : {}),
                    ...(CONFIRM_GEN_IGNORE_STAGED ? { ignore_staged: true } : {}),
                    // Provider, model, its options, quality, size -- and the
                    // prompt only when it was actually changed: sending the
                    // unedited text as an override would set promptIsFinal and
                    // silently stop the references and the style preset.
                    ...confirmChoices(),
                }),
            });
            done();
            // Which provider actually served it. The chain walks past a
            // provider that declines, so "it worked" and "it worked on the one
            // you configured" are different facts.
            const via = res && (res.provider || (res.attempts && res.attempts.length > 1
                ? res.attempts[res.attempts.length - 1].provider : null));
            setStatus(via ? `Frame regenerated via ${via}.` : 'Frame regenerated.');
            await loadStoryboard();
        } catch (err) {
            done();
            setStatus('Could not regenerate: ' + err.message);
        }
    }

    /**
     * Mark one frame as working, and return the function that clears it.
     *
     * Returned rather than cleared by id, so a caller cannot forget which frame
     * it started and leave a card spinning forever over a request that failed.
     */
    /**
     * Mark EVERY surface showing this shot as working, and return the undo.
     *
     * Regen can be pressed from three places — the board card, the full-screen
     * viewer's toolbar, and the shot detail panel — and this marked only the
     * board card. Press it from the viewer and the overlay was appended to a
     * card sitting behind the modal, so it did exist and could not be seen;
     * press it from the detail panel and the card is not on screen at all, so
     * the function returned a no-op and marked nothing. Both look identical to
     * a button that does nothing, which is what got reported twice.
     *
     * Set-based over the surfaces rather than a lookup of one, because a
     * fourth place to press Regen will be added and this has already been wrong
     * about which one is on screen.
     */
    function frameBusy(shotId, label) {
        const SURFACES = [
            // The board card.
            () => document.getElementById('img-' + shotId),
            // The full-screen viewer, but only when it is showing THIS shot —
            // veiling someone else's frame is worse than veiling nothing.
            () => (frameViewerShotId() === shotId ? document.getElementById('frameViewerImg') : null),
            // The shot detail panel.
            () => {
                const panel = document.getElementById('shotDetailPanel');
                return panel ? panel.querySelector('img') : null;
            },
        ];

        const started = Date.now();
        const veils = [];
        const buttons = [];
        BUSY.count++;

        for (const find of SURFACES) {
            let img = null;
            try { img = find(); } catch (_) { img = null; }
            const host = img && img.parentElement;
            if (!host || !host.offsetParent) continue;      // not on screen: nothing to mark
            if (getComputedStyle(host).position === 'static') host.style.position = 'relative';

            const veil = document.createElement('div');
            veil.className = 'frame-busy';
            veil.innerHTML = `<div class="frame-busy-inner">
                <div class="frame-busy-spinner"></div>
                <div class="frame-busy-label">${esc(label || 'Working')} <span data-elapsed>0s</span></div>
            </div>`;
            host.appendChild(veil);
            veils.push(veil);

            const card = host.closest('.card') || host.closest('#shotDetailPanel') || host;
            card.querySelectorAll('button').forEach(b => {
                if (b.disabled) return;
                b.disabled = true; b.style.opacity = '.5';
                buttons.push(b);
            });
        }

        const tick = setInterval(() => {
            const secs = Math.round((Date.now() - started) / 1000);
            const text = secs >= 60
                ? `${Math.floor(secs / 60)}m ${String(secs % 60).padStart(2, '0')}s` : `${secs}s`;
            veils.forEach(v => {
                const el = v.querySelector('[data-elapsed]');
                if (el) el.textContent = text;
            });
        }, 1000);

        let cleared = false;
        return () => {
            // Guarded: a caller that clears twice would drive the counter
            // negative and suppress every background refresh for the session.
            if (cleared) return;
            cleared = true;
            clearInterval(tick);
            veils.forEach(v => v.remove());
            buttons.forEach(b => { b.disabled = false; b.style.opacity = ''; });
            BUSY.count = Math.max(0, BUSY.count - 1);
            if (BUSY.count === 0 && BUSY.pending) {
                BUSY.pending = false;
                LAST_RELOAD = 0;          // the throttle must not swallow the deferred one
                refreshCurrentPage('deferred');
            }
        };
    }

    // ══════════════════════════════════════════════════════════════
    // SHOT CARD EDITOR (FILM-068)
    // ══════════════════════════════════════════════════════════════
    let shotDetailPanel = null;

    /*
     * THE DELIVERY LINE on a video confirmation: the size the project delivers,
     * the size this generator will render, and whether that is a downgrade.
     * Every generator is asked for the delivery size; one that cannot reach it
     * renders its best, and this is where that is said before anything is bought.
     */
    function deliveryLineHtml(dl) {
        if (!dl || !dl.asked) return '';
        const down = dl.downgraded && !dl.draft;
        return `<div class="text-sm" data-delivery-line style="margin:6px 0;${down ? 'color:var(--warning,#b8860b);' : ''}">
            Delivery ${esc(dl.asked)} &middot; this generator renders ${esc(dl.delivered || 'an unreported size')}
            ${dl.draft ? ' &middot; a draft, on purpose' : down ? ' &middot; <strong>below delivery</strong> — its best; upscale after' : ' &middot; full size'}
            ${dl.why ? `<div class="text-muted">${esc(dl.why)}</div>` : ''}</div>`;
    }

    /*
     * THE SHOT'S RECORDED DIALOGUE, offered as an audio reference when the shot
     * has any. Seedance 2.5 takes it; the line under the box says what happens
     * (on MuAPI the board frame becomes a reference, not the exact first frame).
     */
    function dialogueAudioRowHtml(da) {
        if (!da || !da.available) return '';
        return `<div class="form-group" data-dialogue-audio style="margin:6px 0;">
            <label style="display:flex;gap:8px;align-items:center;">
              <input type="checkbox" id="confirmDialogueAudio">
              Send this shot's recorded dialogue (${da.available} line${da.available === 1 ? '' : 's'}) as an audio reference
            </label>
            <div class="text-sm text-muted">Seedance 2.5 only (MuAPI, or seedance2_5 on Runway). On MuAPI it runs the omni-reference workflow, where the storyboard frame is a reference rather than the exact first frame. The preview names anything that cannot be sent.</div>
          </div>`;
    }

    function downloadExport(format) {
        if (!state.currentProject) return;
        const pid = state.currentProject.id;
        const urls = {
            fcpxml: API() + '/projects/' + pid + '/export/fcpxml',
            edl: API() + '/projects/' + pid + '/export/edl',
            premiere: API() + '/projects/' + pid + '/export/premiere',
            srt: API() + '/projects/' + pid + '/export/srt',
            fdx: API() + '/projects/' + pid + '/export/fdx',
        };
        if (urls[format]) {
            window.open(urls[format], '_blank');
            setStatus('Downloading ' + format.toUpperCase() + '...');
        }
    }

    async function importBundle(input) {
        const file = input.files && input.files[0];
        if (!file) return;
        // Show status in whichever page has a status element
        const statusEl = document.getElementById('importStatus') || document.getElementById('projectImportStatus');
        if (statusEl) { statusEl.style.display = 'block'; statusEl.textContent = 'Reading file...'; statusEl.style.color = ''; }

        try {
            const arrayBuf = await file.arrayBuffer();
            const bytes = new Uint8Array(arrayBuf);
            let binary = '';
            for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
            const base64 = btoa(binary);
            if (statusEl) statusEl.textContent = 'Uploading and importing...';
            checkUploadSize(file, '/projects/import');
            const result = await api('/projects/import', {
                method: 'POST',
                body: { bundle: base64 },
            });
            if (statusEl) { statusEl.style.color = 'var(--gl-success)'; statusEl.textContent = 'Imported: ' + (result.project ? result.project.title : 'project') + ' (assets: ' + (result.stats ? result.stats.assets_copied : 0) + ')'; }
            setStatus('Project imported successfully');
            await loadProjects();
        } catch (err) {
            if (statusEl) { statusEl.style.color = 'var(--gl-error)'; statusEl.textContent = 'Import failed: ' + err.message; }
            setStatus('Import failed: ' + err.message);
        }
        input.value = '';
    }

    // ==== CLAUDE:START editorial JS (gaps 3/4/5/7d) ====
    // Gap 3: in-app playback. Gap 4: notes pinned to a moment.
    // Gap 5: circled takes + selects reel. Gap 7d: prompt diff between takes.

    const pb = {
        timeline: null,
        notes: [],
        index: 0,        // which shot is on screen
        playing: false,
        raf: null,
        // Position within the CURRENT shot, ms. The absolute timeline position
        // is this plus the current entry's start_ms — kept separate because the
        // <video> element only ever knows about one clip at a time.
        localMs: 0,
    };


    /*
     * ── Which shot are you on ─────────────────────────────────────────────
     *
     * Playback opened at the first shot every time, so watching the shot you
     * had just spent an hour on meant scrubbing past everything before it.
     *
     * Nothing on the board recorded which shot a director was working on, which
     * is why the page had nothing better to start from: the frame viewer tracks
     * its own index, the Direct modal knows its own shot, and neither left a
     * mark anyone else could read. One mark, dropped by every action that means
     * "I am on this shot now".
     */
    function markCurrentShot(shotId) {
        if (shotId) state.currentShotId = shotId;
    }

    /**
     * Map a stored file path to something the browser can request. The backend
     * serves generated media under /film/video, /film/storyboards etc.; absolute
     * disk paths are not fetchable, so fall back to the basename route.
     */
    function mediaUrl(path) {
        if (!path) return '';
        if (/^https?:\/\//.test(path)) return path;
        // API_BASE is the bare origin; API() already appends /film. Media routes
        // carry their own /film prefix, so build these off API_BASE or the path
        // doubles to /film/film/... — exactly how this broke the first time, and
        // it 404s silently behind a generic "Not found".
        if (path.startsWith('/film/')) return API_BASE + path;
        const pid = state.currentProject && state.currentProject.id;
        const file = String(path).split('/').pop();
        if (!pid || !file) return path;
        /*
         * The serving route comes from the file's OWN directory.
         *
         * Everything non-image used to go to /film/video/, which is right for a
         * clip and 404s for dialogue: audio is written to data/audio/<pid>/ and
         * served at /film/audio/. The result was an <audio> element with a
         * perfectly good src that never loaded — the same fault servedUrlFor
         * had when it derived the subdirectory positionally.
         *
         * Read from the path rather than guessed from the extension, because
         * .mp3 is served from two different places: dialogue from /film/audio
         * and a score from /film/music.
         */
        const SERVED = ['audio', 'video', 'music', 'storyboards', 'refsheets', 'auditions', '3d'];
        const parts = String(path).split('/');
        const dir = parts.find(seg => SERVED.includes(seg));
        if (dir) return `${API_BASE}/film/${dir}/${pid}/${file}`;
        if (/\.(png|jpg|jpeg|webp)$/i.test(file)) return `${API_BASE}/film/storyboards/${pid}/${file}`;
        return `${API_BASE}/film/video/${pid}/${file}`;
    }

    // ── Gap 5 + 7d: selects and prompt diff ──
    const sel = { data: null, shotId: null, takes: [] };


    // ==== CLAUDE:END ====

