    // UTILITIES
    // ══════════════════════════════════════════════════════════════
    function esc(str) {
        if (str == null) return '';
        return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
    }

    /**
     * Say what is happening, and show that it still is.
     *
     * `busy` grows the bar and starts a moving stripe. The stripe is
     * INDETERMINATE on purpose: a plate is one blocking request to a provider
     * that reports no progress, so any percentage would be invented, and an
     * invented percentage that sticks at 60% for two minutes is worse than
     * none. The elapsed counter is the honest version — it is a fact, and it
     * is what tells you the difference between slow and hung.
     */
    let STATUS_TIMER = null;
    let STATUS_STARTED = 0;

    function setStatus(text, busy) {
        const el = document.getElementById('statusText');
        if (el) el.textContent = text;
        const bar = document.getElementById('statusBar');
        const elapsed = document.getElementById('statusElapsed');
        if (!bar) return;

        if (busy) {
            bar.classList.add('busy');
            STATUS_STARTED = Date.now();
            clearInterval(STATUS_TIMER);
            STATUS_TIMER = setInterval(() => {
                const s = Math.round((Date.now() - STATUS_STARTED) / 1000);
                if (elapsed) elapsed.textContent = s >= 60
                    ? `· ${Math.floor(s / 60)}m ${String(s % 60).padStart(2, '0')}s`
                    : `· ${s}s`;
            }, 1000);
        } else {
            bar.classList.remove('busy');
            clearInterval(STATUS_TIMER);
            STATUS_TIMER = null;
            if (elapsed) elapsed.textContent = '';
        }
    }

    async function checkHealth() {
        try {
            const res = await fetch(API_BASE + '/api/health');
            if (res.ok) {
                document.getElementById('statusConnection').innerHTML = '<span class="status-dot-online">&#9679;</span> Connected';
            } else throw new Error();
        } catch (e) {
            document.getElementById('statusConnection').innerHTML = '<span class="status-dot-offline">&#9679;</span> Offline';
        }
    }

